const junipermistTranslations = {
    es: {"nav.guides":"Guías","nav.compare":"Comparar","nav.about":"Acerca de","review.juniper-mist.overview":"Descripción general","review.juniper-mist.juniper.mist.ai.represents.a":"Juniper Mist AI representa un enfoque fundamentalmente diferente para la gestión de redes. A diferencia de los proveedores tradicionales que agregaron características de IA a productos existentes, Mist fue construido desde cero como una plataforma nativa de IA. Adquirido por Juniper Networks en 2019, Mist se ha convertido en la piedra angular de la estrategia empresarial impulsada por IA de Juniper.","review.juniper-mist.the.platforms.crown.jewel.is":"La joya de la corona de la plataforma es Marvis, un asistente de red virtual que utiliza procesamiento de lenguaje natural para responder preguntas, solucionar problemas y proporcionar información. En lugar de buscar en paneles de control y registros, simplemente puede preguntarle a Marvis \"¿Por qué el WiFi de la sala de conferencias es lento?\" y obtener una respuesta accionable.","review.juniper-mist.mist.covers.the.full.network":"Mist cubre la pila de red completa: inalámbrico (Wi-Fi 6/6E), conmutación cableada y SD-WAN. Su arquitectura nativa de la nube significa que no hay controladores que implementar: todo se gestiona a través de un único portal en la nube con IA analizando continuamente sus datos de red.","review.juniper-mist.meet.marvis.your.ai.network":"Conozca a Marvis: Su asistente de red con IA","review.juniper-mist.why.are.users.in.building":"\"¿Por qué los usuarios del Edificio A se quejan de las videollamadas?\" Marvis analiza los datos y responde: \"3 puntos de acceso en el Edificio A experimentan una alta utilización de canales durante las videollamadas. Acción sugerida: Habilite la dirección de banda y agregue un AP en la Sala de Conferencias 2.\"","review.juniper-mist.key.features":"Características principales","review.juniper-mist.conversational.troubleshooting.with.natural.language":"Solución de problemas conversacional con lenguaje natural. Haga preguntas en inglés simple y obtenga respuestas inteligentes y conscientes del contexto sobre problemas de red.","review.juniper-mist.automated.network.optimization.without.human":"Optimización automática de red sin intervención humana. La IA ajusta continuamente la configuración de RF, identifica problemas y recomienda remedios.","review.juniper-mist.sle.dashboards.measure.actual.user":"Los paneles de SLE miden la experiencia real del usuario, no solo las métricas de infraestructura. Rastreie tiempo de conexión, rendimiento, cobertura y rendimiento de aplicaciones.","review.juniper-mist.marvis.automatically.correlates.events.across":"Marvis correlaciona automáticamente eventos en toda la red para identificar las causas raíz. No más análisis manual de registros o conjeturas.","review.juniper-mist.ai-driven.wireless.optimization.including.dynamic":"Optimización inalámbrica impulsada por IA, incluida la gestión dinámica de canales y potencia, dirección de clientes y mitigación de interferencias.","review.juniper-mist.extend.ai.insights.to.sd-wan":"Amplíe la información de IA a implementaciones de SD-WAN. Marvis monitorea la salud del circuito, el rendimiento de las aplicaciones y enruta automáticamente alrededor de los problemas.","review.juniper-mist.patented.vble.virtual.bluetooth.le":"Tecnología patentada vBLE (Bluetooth LE virtual) para posicionamiento en interiores. Habilite señalización, seguimiento de activos y análisis de ubicación.","review.juniper-mist.100.cloud-managed.with.no.controllers":"100% gestionado en la nube sin controladores que implementar. Las actualizaciones ocurren automáticamente y los modelos de IA mejoran continuamente con aprendizaje global.","review.juniper-mist.pros.cons":"Ventajas y desventajas","review.juniper-mist.advantages":"Ventajas","review.juniper-mist.marvis.ai.is.truly.revolutionary":"Marvis AI es verdaderamente revolucionario","review.juniper-mist.best-in-class.user.experience.metrics.sles":"Métricas de experiencia del usuario de clase mundial (SLE)","review.juniper-mist.100.cloud.no.on-premise":"100% nube - sin controladores locales","review.juniper-mist.conversational.troubleshooting.saves.hours":"La solución de problemas conversacional ahorra horas","review.juniper-mist.excellent.wireless.performance":"Rendimiento inalámbrico excelente","review.juniper-mist.strong.sd-wan.integration":"Integración sólida de SD-WAN","review.juniper-mist.built-in.location.services":"Servicios de ubicación integrados","review.juniper-mist.modern.intuitive.ui":"Interfaz moderna e intuitiva","review.juniper-mist.api-first.architecture":"Arquitectura basada en API","review.juniper-mist.continuous.ai.improvement":"Mejora continua de IA","review.juniper-mist.disadvantages":"Desventajas","review.juniper-mist.cloud-only.no.on-premise.option":"Solo nube (sin opción local)","review.juniper-mist.premium.pricing.vs.traditional.vendors":"Precios premium frente a proveedores tradicionales","review.juniper-mist.juniper.switching.ecosystem.less.mature":"Ecosistema de conmutación de Juniper menos maduro","review.juniper-mist.requires.cloud.connectivity":"Requiere conectividad a la nube","review.juniper-mist.smaller.partner.ecosystem.than.cisco":"Ecosistema de socios más pequeño que Cisco","review.juniper-mist.complex.licensing.structure":"Estructura de licencia compleja","review.juniper-mist.limited.legacy.device.support":"Soporte limitado de dispositivos heredados","review.juniper-mist.learning.curve.for.marvis.queries":"Curva de aprendizaje para consultas de Marvis","review.juniper-mist.pricing":"Precios","review.juniper-mist.mist.ai.uses.subscription.licensing":"Mist AI utiliza licencias de suscripción basadas en la cantidad de dispositivos y niveles de características. Todas las licencias incluyen la gestión en la nube y las características de IA: no hay \"complemento de IA\" para comprar por separado.","review.juniper-mist.wi-fi.assurance.150-200apyear.includes.marvis":"Wi-Fi Assurance: ~150-200 $/AP/año (incluye Marvis para inalámbrico)","review.juniper-mist.wired.assurance.50-100switchyear.adds.marvis":"Wired Assurance: ~50-100 $/switch/año (agrega Marvis para cableado)","review.juniper-mist.wan.assurance.100-200edgeyear.sd-wan.with":"WAN Assurance: ~100-200 $/edge/año (SD-WAN con Marvis)","review.juniper-mist.premium.analytics.30-50useryear.advanced.location":"Premium Analytics: ~30-50 $/usuario/año (servicios de ubicación avanzados)","review.juniper-mist.pricing.varies.based.on.term":"Los precios varían según la duración del plazo (1, 3 o 5 años) y el volumen. Contacte a Juniper o a un socio para obtener cotizaciones precisas.","review.juniper-mist.best.use.cases":"Mejores casos de uso","review.juniper-mist.cloud-first.organizations":"Organizaciones en la nube primero","review.juniper-mist.location.services.analytics":"Servicios de ubicación + análisis","review.juniper-mist.asset.tracking.reliability":"Seguimiento de activos + confiabilidad","review.juniper-mist.high-density.wi-fi.sles":"Wi-Fi de alta densidad + SLE","review.juniper-mist.guest.experience.wayfinding":"Experiencia del huésped + señalización","review.juniper-mist.iot.location.intelligence":"IoT + inteligencia de ubicación","review.juniper-mist.recommended.certifications":"Certificaciones recomendadas","review.juniper-mist.to.maximize.the.value.of":"Para maximizar el valor de Juniper Mist AI y avanzar en su carrera de redes inalámbricas, considere estas certificaciones de Juniper reconocidas por la industria. Cada credencial valida habilidades específicas para implementar y gestionar redes inalámbricas impulsadas por IA.","review.juniper-mist.jncia-mistai":"JNCIA-MistAI","review.juniper-mist.foundational.understanding.of.wlan.and":"Comprensión fundamental de la tecnología WLAN y Mist AI, características y funcionalidad.","review.juniper-mist.jncis-mistai.wireless":"JNCIS-MistAI Wireless","review.juniper-mist.advanced.wireless.implementation.with.mist":"Implementación inalámbrica avanzada con Mist AI, incluida solución de problemas y optimización.","review.juniper-mist.jncip-mistai":"JNCIP-MistAI","review.juniper-mist.professional-level.expertise.in.complex.mist":"Experiencia de nivel profesional en implementaciones e integraciones complejas de Mist AI.","review.juniper-mist.final.verdict":"Veredicto final","review.juniper-mist.outstanding":"Excepcional","review.juniper-mist.juniper.mist.ai.sets.the":"Juniper Mist AI establece el estándar para redes impulsadas por IA. Marvis es genuinamente transformador: cambia cómo operan los equipos de red día a día. El enfoque en la experiencia del usuario (SLE) en lugar de solo las métricas de infraestructura es refrescante. Si bien el modelo solo en la nube y los precios premium no serán adecuados para todos, las organizaciones que lo adopten obtendrán un valor excepcional de Mist.","review.juniper-mist.ai.capabilities":"Capacidades de IA","review.juniper-mist.user.experience":"Experiencia del usuario","review.juniper-mist.wireless":"Inalámbrico","review.juniper-mist.value.for.money":"Relación calidad-precio","review.juniper-mist.ecosystem":"Ecosistema","review.juniper-mist.request.demo":"Solicitar demostración →","review.juniper-mist.compare.alternatives":"Comparar alternativas","review.common.screenshots.interface":"Capturas de pantalla e interfaz","review.juniper-mist.explore.juniper.mist.ai-driven.networking":"Explore la red impulsada por IA de Juniper Mist:","review.juniper-mist.frequently.asked.questions":"Preguntas frecuentes","review.juniper-mist.faq.q1":"¿Puede Mist funcionar sin conexión?","review.juniper-mist.faq.a1":"La red en sí continúa funcionando si se pierde la conectividad en la nube — los APs y switches operarán usando políticas en caché. Sin embargo, las características de IA, la gestión y Marvis requieren conectividad en la nube. No hay opción de despliegue en las instalaciones.","review.juniper-mist.faq.q2":"¿Cómo se compara Marvis con Cisco AI?","review.juniper-mist.faq.a2":"Marvis se considera generalmente más avanzado para la solución de problemas conversacional y consultas en lenguaje natural. El AI de Cisco DNA Center es más fuerte para la remediación automatizada en entornos complejos de Cisco. Marvis gana en experiencia del usuario; Cisco gana en profundidad de integración.","review.juniper-mist.faq.q3":"¿Necesito switches Juniper para Mist?","review.juniper-mist.faq.a3":"No, Mist wireless funciona con cualquier infraestructura de switch. Sin embargo, para obtener las características de \"garantía de cableado\" de IA completa y la visibilidad de Marvis en la red cableada, necesita switches Juniper EX gestionados a través de Mist.","review.juniper-mist.faq.q4":"¿Qué hay sobre la soberanía de datos?","review.juniper-mist.faq.a4":"Mist ofrece instancias de nube regional (US, EU, APAC) para abordar los requisitos de soberanía de datos. Sus datos de red permanecen dentro de la región seleccionada. Para industrias altamente reguladas, discuta necesidades de cumplimiento específicas con Juniper."},
    fr: {"nav.guides":"Guides","nav.compare":"Comparer","nav.about":"À propos","review.juniper-mist.overview":"Aperçu","review.juniper-mist.juniper.mist.ai.represents.a":"Juniper Mist AI représente une approche fondamentalement différente de la gestion réseau. Contrairement aux fournisseurs traditionnels qui ont ajouté des fonctionnalités d'IA aux produits existants, Mist a été conçu de zéro comme une plateforme native de l'IA. Acquis par Juniper Networks en 2019, Mist est devenu la pierre angulaire de la stratégie d'entreprise axée sur l'IA de Juniper.","review.juniper-mist.the.platforms.crown.jewel.is":"Le fleuron de la plateforme est Marvis, un assistant réseau virtuel qui utilise le traitement du langage naturel pour répondre aux questions, dépanner les problèmes et fournir des informations. Au lieu de fouiller dans les tableaux de bord et les journaux, vous pouvez simplement demander à Marvis \"Pourquoi le WiFi de la salle de conférence est-il lent ?\" et obtenir une réponse exploitable.","review.juniper-mist.mist.covers.the.full.network":"Mist couvre la pile réseau complète : sans fil (Wi-Fi 6/6E), commutation câblée et SD-WAN. Son architecture native du cloud signifie aucun contrôleur à déployer : tout est géré via un portail cloud unique avec l'IA analysant continuellement vos données réseau.","review.juniper-mist.meet.marvis.your.ai.network":"Rencontrez Marvis : Votre assistant réseau IA","review.juniper-mist.why.are.users.in.building":"\"Pourquoi les utilisateurs du Bâtiment A se plaignent-ils des appels vidéo ?\" Marvis analyse les données et répond : \"3 points d'accès du Bâtiment A connaissent une forte utilisation des canaux lors d'appels vidéo. Action suggérée : Activez la commutation de bande et ajoutez un point d'accès dans la Salle de conférence 2.\"","review.juniper-mist.key.features":"Caractéristiques principales","review.juniper-mist.conversational.troubleshooting.with.natural.language":"Dépannage conversationnel avec langage naturel. Posez des questions en anglais simple et obtenez des réponses intelligentes et contextuelles sur les problèmes réseau.","review.juniper-mist.automated.network.optimization.without.human":"Optimisation réseau automatisée sans intervention humaine. L'IA ajuste continuellement les paramètres RF, identifie les problèmes et recommande des corrections.","review.juniper-mist.sle.dashboards.measure.actual.user":"Les tableaux de bord SLE mesurent l'expérience réelle de l'utilisateur, pas seulement les métriques d'infrastructure. Suivez le temps de connexion, le débit, la couverture et les performances des applications.","review.juniper-mist.marvis.automatically.correlates.events.across":"Marvis met automatiquement en corrélation les événements sur l'ensemble du réseau pour identifier les causes profondes. Fini l'analyse manuelle des journaux ou les devinettes.","review.juniper-mist.ai-driven.wireless.optimization.including.dynamic":"Optimisation sans fil pilotée par l'IA incluant la gestion dynamique des canaux et de la puissance, la direction des clients et l'atténuation des interférences.","review.juniper-mist.extend.ai.insights.to.sd-wan":"Étendez les informations de l'IA aux déploiements SD-WAN. Marvis surveille la santé des circuits, les performances des applications et achemine automatiquement autour des problèmes.","review.juniper-mist.patented.vble.virtual.bluetooth.le":"Technologie vBLE (Bluetooth LE virtuel) brevetée pour le positionnement en intérieur. Activez la signalisation, le suivi d'actifs et l'analytique de localisation.","review.juniper-mist.100.cloud-managed.with.no.controllers":"100% gérés dans le cloud sans contrôleur à déployer. Les mises à jour se font automatiquement et les modèles IA s'améliorent continuellement avec l'apprentissage global.","review.juniper-mist.pros.cons":"Avantages et inconvénients","review.juniper-mist.advantages":"Avantages","review.juniper-mist.marvis.ai.is.truly.revolutionary":"Marvis AI est véritablement révolutionnaire","review.juniper-mist.best-in-class.user.experience.metrics.sles":"Métriques d'expérience utilisateur de classe mondiale (SLE)","review.juniper-mist.100.cloud.no.on-premise":"100% cloud — pas de contrôleurs sur site","review.juniper-mist.conversational.troubleshooting.saves.hours":"Le dépannage conversationnel économise des heures","review.juniper-mist.excellent.wireless.performance":"Excellent rendement sans fil","review.juniper-mist.strong.sd-wan.integration":"Intégration SD-WAN solide","review.juniper-mist.built-in.location.services":"Services de localisation intégrés","review.juniper-mist.modern.intuitive.ui":"Interface moderne et intuitive","review.juniper-mist.api-first.architecture":"Architecture basée sur l'API","review.juniper-mist.continuous.ai.improvement":"Amélioration continue de l'IA","review.juniper-mist.disadvantages":"Inconvénients","review.juniper-mist.cloud-only.no.on-premise.option":"Cloud uniquement (pas d'option sur site)","review.juniper-mist.premium.pricing.vs.traditional.vendors":"Tarification premium par rapport aux fournisseurs traditionnels","review.juniper-mist.juniper.switching.ecosystem.less.mature":"Écosystème de commutation Juniper moins mature","review.juniper-mist.requires.cloud.connectivity":"Nécessite une connectivité cloud","review.juniper-mist.smaller.partner.ecosystem.than.cisco":"Écosystème de partenaires plus petit que Cisco","review.juniper-mist.complex.licensing.structure":"Structure de licence complexe","review.juniper-mist.limited.legacy.device.support":"Support limité des appareils hérités","review.juniper-mist.learning.curve.for.marvis.queries":"Courbe d'apprentissage pour les requêtes Marvis","review.juniper-mist.pricing":"Tarification","review.juniper-mist.mist.ai.uses.subscription.licensing":"Mist AI utilise des licences par abonnement basées sur le nombre d'appareils et les niveaux de fonctionnalités. Toutes les licences incluent la gestion cloud et les fonctionnalités IA : il n'y a pas de \"module IA\" à acheter séparément.","review.juniper-mist.wi-fi.assurance.150-200apyear.includes.marvis":"Wi-Fi Assurance : ~150-200 $/AP/an (inclut Marvis pour le sans fil)","review.juniper-mist.wired.assurance.50-100switchyear.adds.marvis":"Wired Assurance : ~50-100 $/commutateur/an (ajoute Marvis pour le câblé)","review.juniper-mist.wan.assurance.100-200edgeyear.sd-wan.with":"WAN Assurance : ~100-200 $/edge/an (SD-WAN avec Marvis)","review.juniper-mist.premium.analytics.30-50useryear.advanced.location":"Premium Analytics : ~30-50 $/utilisateur/an (services de localisation avancés)","review.juniper-mist.pricing.varies.based.on.term":"La tarification varie en fonction de la durée du contrat (1, 3 ou 5 ans) et du volume. Contactez Juniper ou un partenaire pour des devis précis.","review.juniper-mist.best.use.cases":"Meilleurs cas d'utilisation","review.juniper-mist.cloud-first.organizations":"Organisations cloud-first","review.juniper-mist.location.services.analytics":"Services de localisation + analytique","review.juniper-mist.asset.tracking.reliability":"Suivi d'actifs + fiabilité","review.juniper-mist.high-density.wi-fi.sles":"Wi-Fi haute densité + SLE","review.juniper-mist.guest.experience.wayfinding":"Expérience client + signalisation","review.juniper-mist.iot.location.intelligence":"IoT + intelligence de localisation","review.juniper-mist.recommended.certifications":"Certifications recommandées","review.juniper-mist.to.maximize.the.value.of":"Pour maximiser la valeur de Juniper Mist AI et avancer dans votre carrière de réseau sans fil, envisagez ces certifications Juniper reconnues par l'industrie. Chaque titre valide des compétences spécifiques pour implémenter et gérer des réseaux sans fil pilotés par l'IA.","review.juniper-mist.jncia-mistai":"JNCIA-MistAI","review.juniper-mist.foundational.understanding.of.wlan.and":"Compréhension fondamentale de la technologie WLAN et Mist AI, des fonctionnalités et des fonctionnalités.","review.juniper-mist.jncis-mistai.wireless":"JNCIS-MistAI Wireless","review.juniper-mist.advanced.wireless.implementation.with.mist":"Implémentation sans fil avancée avec Mist AI, y compris le dépannage et l'optimisation.","review.juniper-mist.jncip-mistai":"JNCIP-MistAI","review.juniper-mist.professional-level.expertise.in.complex.mist":"Expertise de niveau professionnel dans les déploiements et intégrations complexes de Mist AI.","review.juniper-mist.final.verdict":"Verdict final","review.juniper-mist.outstanding":"Exceptionnel","review.juniper-mist.juniper.mist.ai.sets.the":"Juniper Mist AI établit la norme pour la mise en réseau pilotée par l'IA. Marvis est véritablement transformateur : il change la façon dont les équipes réseau opèrent au quotidien. L'accent mis sur l'expérience utilisateur (SLE) plutôt que sur les simples métriques d'infrastructure est rafraîchissant. Bien que le modèle cloud uniquement et la tarification premium ne conviennent pas à tous, pour les organisations qui l'adoptent, Mist offre une valeur exceptionnelle.","review.juniper-mist.ai.capabilities":"Capacités d'IA","review.juniper-mist.user.experience":"Expérience utilisateur","review.juniper-mist.wireless":"Sans fil","review.juniper-mist.value.for.money":"Rapport qualité-prix","review.juniper-mist.ecosystem":"Écosystème","review.juniper-mist.request.demo":"Demander une démo →","review.juniper-mist.compare.alternatives":"Comparer les alternatives","review.common.screenshots.interface":"Captures d'écran et interface","review.juniper-mist.explore.juniper.mist.ai-driven.networking":"Explorez la mise en réseau pilotée par l'IA de Juniper Mist :","review.juniper-mist.frequently.asked.questions":"Questions fréquemment posées","review.juniper-mist.faq.q1":"Mist peut-il fonctionner hors ligne ?","review.juniper-mist.faq.a1":"Le réseau lui-même continue de fonctionner si la connectivité cloud est perdue — les APs et les commutateurs fonctionneront en utilisant des stratégies en cache. Cependant, les fonctionnalités d'IA, la gestion et Marvis nécessitent une connectivité cloud. Il n'y a pas d'option de déploiement sur site.","review.juniper-mist.faq.q2":"Comment Marvis se compare-t-il à Cisco AI ?","review.juniper-mist.faq.a2":"Marvis est généralement considéré comme plus avancé pour la résolution de problèmes conversationnelle et les requêtes en langage naturel. Cisco DNA Center AI est plus puissant pour la remédiation automatisée dans les environnements Cisco complexes. Marvis gagne en expérience utilisateur ; Cisco gagne en profondeur d'intégration.","review.juniper-mist.faq.q3":"Ai-je besoin de commutateurs Juniper pour Mist ?","review.juniper-mist.faq.a3":"Non, Mist sans fil fonctionne avec n'importe quelle infrastructure de commutateur. Cependant, pour obtenir les fonctionnalités d'IA \"assurance filaire\" complètes et la visibilité Marvis dans le réseau filaire, vous avez besoin de commutateurs Juniper EX gérés via Mist.","review.juniper-mist.faq.q4":"Qu'en est-il de la souveraineté des données ?","review.juniper-mist.faq.a4":"Mist propose des instances cloud régionales (US, EU, APAC) pour répondre aux exigences de souveraineté des données. Vos données réseau restent dans la région sélectionnée. Pour les secteurs hautement réglementés, discutez des besoins de conformité spécifiques avec Juniper."},
    de: {"nav.guides":"Leitfäden","nav.compare":"Vergleichen","nav.about":"Über uns","review.juniper-mist.overview":"Übersicht","review.juniper-mist.juniper.mist.ai.represents.a":"Juniper Mist AI stellt einen grundlegend anderen Ansatz für Netzwerkverwaltung dar. Im Gegensatz zu traditionellen Anbietern, die KI-Funktionen zu bestehenden Produkten hinzugefügt haben, wurde Mist von Grund auf als native KI-Plattform aufgebaut. Nach der Übernahme durch Juniper Networks im Jahr 2019 ist Mist zum Eckpfeiler von Junipers KI-gestützter Unternehmensstrategie geworden.","review.juniper-mist.the.platforms.crown.jewel.is":"Das Flaggschiff der Plattform ist Marvis – ein virtueller Netzwerk-Assistent, der natürliche Sprachverarbeitung nutzt, um Fragen zu beantworten, Probleme zu beheben und Einblicke zu geben. Anstatt sich durch Dashboards und Protokolle zu wühlen, können Sie einfach Marvis fragen \"Warum ist das WiFi im Konferenzraum langsam?\" und erhalten eine handlungsfähige Antwort.","review.juniper-mist.mist.covers.the.full.network":"Mist deckt den kompletten Netzwerk-Stack ab: drahtlos (Wi-Fi 6/6E), verkabeltes Switching und SD-WAN. Die Cloud-native Architektur bedeutet, dass es keine zu implementierenden Controller gibt – alles wird über ein einziges Cloud-Portal verwaltet, während die KI kontinuierlich Ihre Netzwerkdaten analysiert.","review.juniper-mist.meet.marvis.your.ai.network":"Treffen Sie Marvis: Ihr KI-Netzwerk-Assistent","review.juniper-mist.why.are.users.in.building":"\"Warum beschweren sich Benutzer in Gebäude A über Videoanrufe?\" Marvis analysiert die Daten und antwortet: \"3 Access Points in Gebäude A erleben hohe Kanalauslastung während Videoanrufen. Empfohlene Maßnahme: Aktivieren Sie Band-Steuerung und fügen Sie einen AP im Konferenzraum 2 hinzu.\"","review.juniper-mist.key.features":"Wichtigste Funktionen","review.juniper-mist.conversational.troubleshooting.with.natural.language":"Problembehebung im Gespräch mit natürlicher Sprache. Stellen Sie Fragen auf einfaches Englisch und erhalten Sie intelligente, kontextbewusste Antworten zu Netzwerkproblemen.","review.juniper-mist.automated.network.optimization.without.human":"Automatisierte Netzwerkoptimierung ohne menschliches Zutun. Die KI passt kontinuierlich HF-Einstellungen an, identifiziert Probleme und empfiehlt Abhilfemaßnahmen.","review.juniper-mist.sle.dashboards.measure.actual.user":"SLE-Dashboards messen die tatsächliche Benutzererfahrung, nicht nur Infrastruktur-Metriken. Verfolgen Sie Verbindungszeit, Durchsatz, Abdeckung und Anwendungsleistung.","review.juniper-mist.marvis.automatically.correlates.events.across":"Marvis korreliert automatisch Ereignisse im gesamten Netzwerk, um Grundursachen zu identifizieren. Keine manuellen Protokollanalysen oder Rätselraten mehr.","review.juniper-mist.ai-driven.wireless.optimization.including.dynamic":"KI-gesteuerte Wireless-Optimierung mit dynamischer Kanal- und Leistungsverwaltung, Client-Steuerung und Interferenzbegrenzung.","review.juniper-mist.extend.ai.insights.to.sd-wan":"Erweitern Sie KI-Einblicke auf SD-WAN-Implementierungen. Marvis überwacht die Schaltungsgesundheit, Anwendungsleistung und leitet automatisch um Probleme herum.","review.juniper-mist.patented.vble.virtual.bluetooth.le":"Patentierte vBLE-Technologie (virtuelles Bluetooth LE) für Innenpositionierung. Aktivieren Sie Wegfindung, Asset-Tracking und Standortanalysen.","review.juniper-mist.100.cloud-managed.with.no.controllers":"100% Cloud-verwaltet ohne zu implementierende Controller. Updates erfolgen automatisch und KI-Modelle verbessern sich kontinuierlich durch globales Lernen.","review.juniper-mist.pros.cons":"Vor- und Nachteile","review.juniper-mist.advantages":"Vorteile","review.juniper-mist.marvis.ai.is.truly.revolutionary":"Marvis AI ist wirklich revolutionär","review.juniper-mist.best-in-class.user.experience.metrics.sles":"Weltklasse-Benutzererfahrungsmetriken (SLE)","review.juniper-mist.100.cloud.no.on-premise":"100% Cloud – keine lokalen Controller","review.juniper-mist.conversational.troubleshooting.saves.hours":"Problembehebung im Gespräch spart Stunden","review.juniper-mist.excellent.wireless.performance":"Hervorragende Wireless-Leistung","review.juniper-mist.strong.sd-wan.integration":"Starke SD-WAN-Integration","review.juniper-mist.built-in.location.services":"Integrierte Standortdienste","review.juniper-mist.modern.intuitive.ui":"Moderne, intuitive Benutzeroberfläche","review.juniper-mist.api-first.architecture":"API-zentrierte Architektur","review.juniper-mist.continuous.ai.improvement":"Kontinuierliche KI-Verbesserung","review.juniper-mist.disadvantages":"Nachteile","review.juniper-mist.cloud-only.no.on-premise.option":"Nur Cloud (keine lokale Option)","review.juniper-mist.premium.pricing.vs.traditional.vendors":"Premium-Preisgestaltung vs. traditionelle Anbieter","review.juniper-mist.juniper.switching.ecosystem.less.mature":"Juniper-Switching-Ökosystem weniger reif","review.juniper-mist.requires.cloud.connectivity":"Erfordert Cloud-Konnektivität","review.juniper-mist.smaller.partner.ecosystem.than.cisco":"Kleineres Partner-Ökosystem als Cisco","review.juniper-mist.complex.licensing.structure":"Komplexe Lizenzstruktur","review.juniper-mist.limited.legacy.device.support":"Begrenzte Unterstützung für ältere Geräte","review.juniper-mist.learning.curve.for.marvis.queries":"Lernkurve für Marvis-Anfragen","review.juniper-mist.pricing":"Preisgestaltung","review.juniper-mist.mist.ai.uses.subscription.licensing":"Mist AI verwendet Abonnementlizenzen basierend auf der Geräteanzahl und Feature-Stufen. Alle Lizenzen beinhalten Cloud-Verwaltung und KI-Funktionen – es gibt keine separate \"KI-Add-on\" zum Kaufen.","review.juniper-mist.wi-fi.assurance.150-200apyear.includes.marvis":"Wi-Fi Assurance: ~150-200 $/AP/Jahr (einschließlich Marvis für Wireless)","review.juniper-mist.wired.assurance.50-100switchyear.adds.marvis":"Wired Assurance: ~50-100 $/Switch/Jahr (fügt Marvis für Verkabelung hinzu)","review.juniper-mist.wan.assurance.100-200edgeyear.sd-wan.with":"WAN Assurance: ~100-200 $/Edge/Jahr (SD-WAN mit Marvis)","review.juniper-mist.premium.analytics.30-50useryear.advanced.location":"Premium Analytics: ~30-50 $/Benutzer/Jahr (erweiterte Standortdienste)","review.juniper-mist.pricing.varies.based.on.term":"Die Preisgestaltung variiert je nach Vertragslaufzeit (1, 3 oder 5 Jahre) und Volumen. Kontaktieren Sie Juniper oder einen Partner für genaue Angebote.","review.juniper-mist.best.use.cases":"Beste Anwendungsfälle","review.juniper-mist.cloud-first.organizations":"Cloud-First-Organisationen","review.juniper-mist.location.services.analytics":"Standortdienste + Analytik","review.juniper-mist.asset.tracking.reliability":"Asset-Tracking + Zuverlässigkeit","review.juniper-mist.high-density.wi-fi.sles":"Hochdichten-Wi-Fi + SLE","review.juniper-mist.guest.experience.wayfinding":"Gastkokerleben + Wegfindung","review.juniper-mist.iot.location.intelligence":"IoT + Standortintelligenz","review.juniper-mist.recommended.certifications":"Empfohlene Zertifizierungen","review.juniper-mist.to.maximize.the.value.of":"Um den Wert von Juniper Mist AI zu maximieren und Ihre Karriere im Wireless-Netzwerk voranzutreiben, erwägen Sie diese branchenweit anerkannten Juniper-Zertifizierungen. Jeder Titel validiert spezifische Fähigkeiten zum Implementieren und Verwalten von KI-gesteuerten Wireless-Netzwerken.","review.juniper-mist.jncia-mistai":"JNCIA-MistAI","review.juniper-mist.foundational.understanding.of.wlan.and":"Grundlegendes Verständnis der WLAN- und Mist AI-Technologie, Funktionen und Funktionalität.","review.juniper-mist.jncis-mistai.wireless":"JNCIS-MistAI Wireless","review.juniper-mist.advanced.wireless.implementation.with.mist":"Fortgeschrittene Wireless-Implementierung mit Mist AI, einschließlich Troubleshooting und Optimierung.","review.juniper-mist.jncip-mistai":"JNCIP-MistAI","review.juniper-mist.professional-level.expertise.in.complex.mist":"Expertise auf professioneller Ebene bei komplexen Mist AI-Implementierungen und Integrationen.","review.juniper-mist.final.verdict":"Abschließendes Fazit","review.juniper-mist.outstanding":"Hervorragend","review.juniper-mist.juniper.mist.ai.sets.the":"Juniper Mist AI setzt die Norm für KI-gesteuerte Netzwerke. Marvis ist wirklich transformativ – es ändert, wie Netzwerk-Teams täglich arbeiten. Der Fokus auf Benutzererfahrung (SLE) statt nur Infrastruktur-Metriken ist erfrischend. Während das Cloud-Only-Modell und die Premium-Preisgestaltung nicht für jeden geeignet sind, bietet Mist für Organisationen, die es annehmen, außergewöhnlichen Wert.","review.juniper-mist.ai.capabilities":"KI-Funktionen","review.juniper-mist.user.experience":"Benutzererfahrung","review.juniper-mist.wireless":"Wireless","review.juniper-mist.value.for.money":"Preis-Leistungs-Verhältnis","review.juniper-mist.ecosystem":"Ökosystem","review.juniper-mist.request.demo":"Demo anfordern →","review.juniper-mist.compare.alternatives":"Alternativen vergleichen","review.common.screenshots.interface":"Screenshots und Benutzeroberfläche","review.juniper-mist.explore.juniper.mist.ai-driven.networking":"Erkunden Sie KI-gesteuerte Netzwerke von Juniper Mist:","review.juniper-mist.frequently.asked.questions":"Häufig gestellte Fragen","review.juniper-mist.faq.q1":"Kann Mist offline arbeiten?","review.juniper-mist.faq.a1":"Das Netzwerk selbst funktioniert weiterhin, wenn die Cloud-Konnektivität verloren geht — APs und Switches arbeiten mit zwischengespeicherten Richtlinien. Allerdings erfordern KI-Funktionen, Verwaltung und Marvis Cloud-Konnektivität. Es gibt keine On-Premise-Bereitstellungsoption.","review.juniper-mist.faq.q2":"Wie schneidet Marvis im Vergleich zu Cisco AI ab?","review.juniper-mist.faq.a2":"Marvis gilt allgemein als fortschrittlicher für konversationale Fehlerbehebung und Abfragen in natürlicher Sprache. Cisco DNA Center AI ist stärker bei der automatisierten Behebung in komplexen Cisco-Umgebungen. Marvis gewinnt bei der Benutzerfreundlichkeit; Cisco gewinnt bei der Integrationstiefe.","review.juniper-mist.faq.q3":"Benötige ich Juniper-Switches für Mist?","review.juniper-mist.faq.a3":"Nein, Mist Wireless funktioniert mit jeder Switch-Infrastruktur. Um jedoch die vollständigen \"Wired Assurance\" KI-Funktionen und die Marvis-Sichtbarkeit in das verkabelte Netzwerk zu erhalten, benötigen Sie Juniper EX Switches, die über Mist verwaltet werden.","review.juniper-mist.faq.q4":"Was ist mit Datensouveränität?","review.juniper-mist.faq.a4":"Mist bietet regionale Cloud-Instanzen (US, EU, APAC) um Datensouveränitätsanforderungen zu erfüllen. Ihre Netzwerkdaten bleiben in der ausgewählten Region. Für stark regulierte Branchen sollten Sie spezifische Compliance-Anforderungen mit Juniper besprechen."},
    pt: {"nav.guides":"Guias","nav.compare":"Comparar","nav.about":"Sobre","review.juniper-mist.overview":"Visão Geral","review.juniper-mist.juniper.mist.ai.represents.a":"Juniper Mist AI representa uma abordagem fundamentalmente diferente para gerenciamento de rede. Ao contrário de fornecedores tradicionais que adicionaram recursos de IA aos produtos existentes, Mist foi construído desde o início como uma plataforma nativa de IA. Adquirido pela Juniper Networks em 2019, Mist se tornou a pedra angular da estratégia empresarial orientada por IA da Juniper.","review.juniper-mist.the.platforms.crown.jewel.is":"A joia da coroa da plataforma é Marvis — um assistente de rede virtual que usa processamento de linguagem natural para responder perguntas, resolver problemas e fornecer insights. Em vez de navegar por painéis e logs, você pode simplesmente perguntar a Marvis \"Por que o WiFi da sala de conferências está lento?\" e obter uma resposta acionável.","review.juniper-mist.mist.covers.the.full.network":"Mist cobre a pilha de rede completa: wireless (Wi-Fi 6/6E), comutação cabeada e SD-WAN. Sua arquitetura nativa da nuvem significa sem controladores para implantar — tudo é gerenciado através de um único portal na nuvem com IA analisando continuamente seus dados de rede.","review.juniper-mist.meet.marvis.your.ai.network":"Conheça Marvis: Seu Assistente de Rede com IA","review.juniper-mist.why.are.users.in.building":"\"Por que os usuários no Edifício A estão reclamando de chamadas de vídeo?\" Marvis analisa os dados e responde: \"3 APs no Edifício A estão experimentando alta utilização de canal durante chamadas de vídeo. Ação sugerida: Ativar band steering e adicionar AP na Sala de Conferências 2.\"","review.juniper-mist.key.features":"Principais Recursos","review.juniper-mist.conversational.troubleshooting.with.natural.language":"Solução de problemas conversacional com linguagem natural. Faça perguntas em inglês simples e obtenha respostas inteligentes e conscientes do contexto sobre problemas de rede.","review.juniper-mist.automated.network.optimization.without.human":"Otimização automática de rede sem intervenção humana. A IA ajusta continuamente as configurações de RF, identifica problemas e recomenda remediação.","review.juniper-mist.sle.dashboards.measure.actual.user":"Painéis de SLE medem a experiência real do usuário, não apenas métricas de infraestrutura. Rastreie tempo de conexão, taxa de transferência, cobertura e desempenho de aplicação.","review.juniper-mist.marvis.automatically.correlates.events.across":"Marvis correlaciona automaticamente eventos na rede para identificar causas raiz. Nada mais de análise manual de logs ou adivinhação.","review.juniper-mist.ai-driven.wireless.optimization.including.dynamic":"Otimização de wireless orientada por IA incluindo gerenciamento dinâmico de canal e potência, direcionamento de cliente e mitigação de interferência.","review.juniper-mist.extend.ai.insights.to.sd-wan":"Estenda insights de IA para implantações de SD-WAN. Marvis monitora a saúde do circuito, desempenho da aplicação e roteia automaticamente ao redor de problemas.","review.juniper-mist.patented.vble.virtual.bluetooth.le":"Tecnologia vBLE (virtual Bluetooth LE) patenteada para posicionamento interior. Ative wayfinding, rastreamento de ativos e análise de localização.","review.juniper-mist.100.cloud-managed.with.no.controllers":"100% gerenciado na nuvem sem controladores para implantar. As atualizações acontecem automaticamente e os modelos de IA melhoram continuamente com aprendizado global.","review.juniper-mist.pros.cons":"Prós &amp; Contras","review.juniper-mist.advantages":"Vantagens","review.juniper-mist.marvis.ai.is.truly.revolutionary":"Marvis AI é verdadeiramente revolucionário","review.juniper-mist.best-in-class.user.experience.metrics.sles":"Métricas de experiência do usuário classe mundial (SLEs)","review.juniper-mist.100.cloud.no.on-premise":"100% nuvem — sem controladores locais","review.juniper-mist.conversational.troubleshooting.saves.hours":"Solução de problemas conversacional economiza horas","review.juniper-mist.excellent.wireless.performance":"Excelente desempenho wireless","review.juniper-mist.strong.sd-wan.integration":"Integração SD-WAN forte","review.juniper-mist.built-in.location.services":"Serviços de localização integrados","review.juniper-mist.modern.intuitive.ui":"Interface moderna e intuitiva","review.juniper-mist.api-first.architecture":"Arquitetura API-first","review.juniper-mist.continuous.ai.improvement":"Melhoria contínua de IA","review.juniper-mist.disadvantages":"Desvantagens","review.juniper-mist.cloud-only.no.on-premise.option":"Somente nuvem (sem opção local)","review.juniper-mist.premium.pricing.vs.traditional.vendors":"Preço premium vs fornecedores tradicionais","review.juniper-mist.juniper.switching.ecosystem.less.mature":"Ecossistema de comutação Juniper menos maduro","review.juniper-mist.requires.cloud.connectivity":"Requer conectividade na nuvem","review.juniper-mist.smaller.partner.ecosystem.than.cisco":"Menor ecossistema de parceiros que Cisco","review.juniper-mist.complex.licensing.structure":"Estrutura de licenciamento complexa","review.juniper-mist.limited.legacy.device.support":"Suporte limitado a dispositivos legados","review.juniper-mist.learning.curve.for.marvis.queries":"Curva de aprendizado para consultas de Marvis","review.juniper-mist.pricing":"Preços","review.juniper-mist.mist.ai.uses.subscription.licensing":"Mist AI usa licenciamento por assinatura com base na contagem de dispositivos e níveis de recursos. Todas as licenças incluem gerenciamento na nuvem e recursos de IA — não há \"complemento de IA\" para comprar separadamente.","review.juniper-mist.wi-fi.assurance.150-200apyear.includes.marvis":"Wi-Fi Assurance: ~$150-200/AP/ano (inclui Marvis para wireless)","review.juniper-mist.wired.assurance.50-100switchyear.adds.marvis":"Wired Assurance: ~$50-100/switch/ano (adiciona Marvis para cabeado)","review.juniper-mist.wan.assurance.100-200edgeyear.sd-wan.with":"WAN Assurance: ~$100-200/edge/ano (SD-WAN com Marvis)","review.juniper-mist.premium.analytics.30-50useryear.advanced.location":"Premium Analytics: ~$30-50/usuário/ano (serviços de localização avançados)","review.juniper-mist.pricing.varies.based.on.term":"O preço varia com base no período do termo (1, 3 ou 5 anos) e volume. Entre em contato com a Juniper ou um parceiro para cotações precisas.","review.juniper-mist.best.use.cases":"Melhores Casos de Uso","review.juniper-mist.cloud-first.organizations":"Organizações cloud-first","review.juniper-mist.location.services.analytics":"Serviços de localização + análise","review.juniper-mist.asset.tracking.reliability":"Rastreamento de ativos + confiabilidade","review.juniper-mist.high-density.wi-fi.sles":"Wi-Fi de alta densidade + SLEs","review.juniper-mist.guest.experience.wayfinding":"Experiência do hóspede + wayfinding","review.juniper-mist.iot.location.intelligence":"IoT + inteligência de localização","review.juniper-mist.recommended.certifications":"Certificações Recomendadas","review.juniper-mist.to.maximize.the.value.of":"Para maximizar o valor do Juniper Mist AI e avançar sua carreira de rede wireless, considere essas certificações Juniper reconhecidas pela indústria. Cada credencial valida habilidades específicas para implementação e gerenciamento de redes wireless orientadas por IA.","review.juniper-mist.jncia-mistai":"JNCIA-MistAI","review.juniper-mist.foundational.understanding.of.wlan.and":"Entendimento fundamental de WLAN e tecnologia Mist AI, recursos e funcionalidade.","review.juniper-mist.jncis-mistai.wireless":"JNCIS-MistAI Wireless","review.juniper-mist.advanced.wireless.implementation.with.mist":"Implementação wireless avançada com Mist AI, incluindo solução de problemas e otimização.","review.juniper-mist.jncip-mistai":"JNCIP-MistAI","review.juniper-mist.professional-level.expertise.in.complex.mist":"Experiência em nível profissional em implantações e integrações complexas de Mist AI.","review.juniper-mist.final.verdict":"Veredicto Final","review.juniper-mist.outstanding":"Excepcional","review.juniper-mist.juniper.mist.ai.sets.the":"Juniper Mist AI estabelece o padrão para redes orientadas por IA. Marvis é genuinamente transformador — muda como equipes de rede operam dia a dia. O foco em experiência do usuário (SLEs) em vez de apenas métricas de infraestrutura é refrescante. Enquanto o modelo apenas na nuvem e preço premium não convêm a todos, para organizações que o adotam, Mist oferece valor excepcional.","review.juniper-mist.ai.capabilities":"Capacidades de IA","review.juniper-mist.user.experience":"Experiência do Usuário","review.juniper-mist.wireless":"Wireless","review.juniper-mist.value.for.money":"Valor pelo Dinheiro","review.juniper-mist.ecosystem":"Ecossistema","review.juniper-mist.request.demo":"Solicitar Demo →","review.juniper-mist.compare.alternatives":"Comparar Alternativas","review.common.screenshots.interface":"Capturas de Tela &amp; Interface","review.juniper-mist.explore.juniper.mist.ai-driven.networking":"Explore redes orientadas por IA do Juniper Mist:","review.juniper-mist.frequently.asked.questions":"Perguntas Frequentes","review.juniper-mist.faq.q1":"Mist pode funcionar offline?","review.juniper-mist.faq.a1":"A rede continua funcionando se a conectividade em nuvem for perdida — APs e switches operarão usando políticas armazenadas em cache. No entanto, recursos de IA, gerenciamento e Marvis requerem conectividade em nuvem. Não há opção de implantação local.","review.juniper-mist.faq.q2":"Como Marvis se compara ao Cisco AI?","review.juniper-mist.faq.a2":"Marvis é geralmente considerado mais avançado para resolução de problemas por conversa e consultas em linguagem natural. O Cisco DNA Center AI é mais forte para remediação automatizada em ambientes complexos da Cisco. Marvis vence em experiência do usuário; Cisco vence em profundidade de integração.","review.juniper-mist.faq.q3":"Preciso de switches Juniper para Mist?","review.juniper-mist.faq.a3":"Não, Mist wireless funciona com qualquer infraestrutura de switch. No entanto, para obter todos os recursos de IA de \"garantia de cabo\" e visibilidade de Marvis na rede cabeada, você precisa de switches Juniper EX gerenciados através do Mist.","review.juniper-mist.faq.q4":"E quanto à soberania de dados?","review.juniper-mist.faq.a4":"Mist oferece instâncias de nuvem regionais (EUA, UE, APAC) para atender aos requisitos de soberania de dados. Seus dados de rede permanecem dentro da região selecionada. Para setores altamente regulamentados, discuta necessidades de conformidade específicas com a Juniper."},
    zh: {"nav.guides":"指南","nav.compare":"比较","nav.about":"关于","review.juniper-mist.overview":"概述","review.juniper-mist.juniper.mist.ai.represents.a":"Juniper Mist AI代表了网络管理的根本性不同方法。与传统供应商在现有产品中添加AI功能不同，Mist从一开始就被构建为AI原生平台。在2019年被Juniper Networks收购后，Mist已成为Juniper AI驱动企业战略的基石。","review.juniper-mist.the.platforms.crown.jewel.is":"该平台的皇冠明珠是Marvis——一个虚拟网络助手，使用自然语言处理来回答问题、解决问题和提供见解。您可以简单地询问Marvis \"为什么会议室的WiFi很慢？\"，而不是在仪表板和日志中挖掘，并获得可操作的答案。","review.juniper-mist.mist.covers.the.full.network":"Mist覆盖完整的网络堆栈：无线（Wi-Fi 6/6E）、有线交换和SD-WAN。其云原生架构意味着无需部署控制器——所有内容都通过单个云门户进行管理，AI持续分析您的网络数据。","review.juniper-mist.meet.marvis.your.ai.network":"认识Marvis：您的AI网络助手","review.juniper-mist.why.are.users.in.building":"\"为什么A楼的用户在抱怨视频通话？\" Marvis分析数据并响应：\"A楼的3个AP在视频通话期间经历高信道利用率。建议的操作：启用band steering并在会议室2中添加AP。\"","review.juniper-mist.key.features":"主要特性","review.juniper-mist.conversational.troubleshooting.with.natural.language":"使用自然语言进行会话故障排除。用纯英文提出问题，获得有关网络问题的智能、上下文感知的答案。","review.juniper-mist.automated.network.optimization.without.human":"无人工干预的自动网络优化。AI持续调整RF设置、识别问题并建议修复。","review.juniper-mist.sle.dashboards.measure.actual.user":"SLE仪表板衡量实际用户体验，而不仅仅是基础设施指标。跟踪连接时间、吞吐量、覆盖范围和应用性能。","review.juniper-mist.marvis.automatically.correlates.events.across":"Marvis自动关联网络中的事件以识别根本原因。不再需要手动日志分析或猜测。","review.juniper-mist.ai-driven.wireless.optimization.including.dynamic":"AI驱动的无线优化，包括动态信道和功率管理、客户端转向和干扰缓解。","review.juniper-mist.extend.ai.insights.to.sd-wan":"将AI见解扩展到SD-WAN部署。Marvis监控电路健康状况、应用性能，并自动绕过问题。","review.juniper-mist.patented.vble.virtual.bluetooth.le":"专利vBLE（虚拟蓝牙LE）室内定位技术。启用寻路、资产跟踪和位置分析。","review.juniper-mist.100.cloud-managed.with.no.controllers":"100%云管理，无需部署控制器。更新自动进行，AI模型通过全球学习持续改进。","review.juniper-mist.pros.cons":"优点&amp;缺点","review.juniper-mist.advantages":"优点","review.juniper-mist.marvis.ai.is.truly.revolutionary":"Marvis AI真正革命性","review.juniper-mist.best-in-class.user.experience.metrics.sles":"一流的用户体验指标（SLE）","review.juniper-mist.100.cloud.no.on-premise":"100%云——无本地控制器","review.juniper-mist.conversational.troubleshooting.saves.hours":"会话故障排除节省时间","review.juniper-mist.excellent.wireless.performance":"优秀的无线性能","review.juniper-mist.strong.sd-wan.integration":"强大的SD-WAN集成","review.juniper-mist.built-in.location.services":"内置位置服务","review.juniper-mist.modern.intuitive.ui":"现代直观的UI","review.juniper-mist.api-first.architecture":"API优先架构","review.juniper-mist.continuous.ai.improvement":"持续的AI改进","review.juniper-mist.disadvantages":"缺点","review.juniper-mist.cloud-only.no.on-premise.option":"仅云端（无本地选项）","review.juniper-mist.premium.pricing.vs.traditional.vendors":"与传统供应商相比的高级定价","review.juniper-mist.juniper.switching.ecosystem.less.mature":"Juniper交换生态系统不够成熟","review.juniper-mist.requires.cloud.connectivity":"需要云连接","review.juniper-mist.smaller.partner.ecosystem.than.cisco":"比Cisco的合作伙伴生态系统更小","review.juniper-mist.complex.licensing.structure":"复杂的许可结构","review.juniper-mist.limited.legacy.device.support":"有限的遗留设备支持","review.juniper-mist.learning.curve.for.marvis.queries":"Marvis查询的学习曲线","review.juniper-mist.pricing":"定价","review.juniper-mist.mist.ai.uses.subscription.licensing":"Mist AI使用基于设备数量和功能层级的订阅许可。所有许可都包括云管理和AI功能——没有需要单独购买的\"AI附加组件\"。","review.juniper-mist.wi-fi.assurance.150-200apyear.includes.marvis":"Wi-Fi保证：~$150-200/AP/年（包括无线Marvis）","review.juniper-mist.wired.assurance.50-100switchyear.adds.marvis":"有线保证：~$50-100/交换机/年（添加有线Marvis）","review.juniper-mist.wan.assurance.100-200edgeyear.sd-wan.with":"WAN保证：~$100-200/边缘/年（带Marvis的SD-WAN）","review.juniper-mist.premium.analytics.30-50useryear.advanced.location":"高级分析：~$30-50/用户/年（高级位置服务）","review.juniper-mist.pricing.varies.based.on.term":"定价因合同期限（1、3或5年）和数量而异。请联系Juniper或合作伙伴获取准确报价。","review.juniper-mist.best.use.cases":"最佳用例","review.juniper-mist.cloud-first.organizations":"云优先的组织","review.juniper-mist.location.services.analytics":"位置服务+分析","review.juniper-mist.asset.tracking.reliability":"资产跟踪+可靠性","review.juniper-mist.high-density.wi-fi.sles":"高密度Wi-Fi + SLE","review.juniper-mist.guest.experience.wayfinding":"客人体验+寻路","review.juniper-mist.iot.location.intelligence":"物联网+位置智能","review.juniper-mist.recommended.certifications":"推荐的认证","review.juniper-mist.to.maximize.the.value.of":"为了最大化Juniper Mist AI的价值并推进您的无线网络职业生涯，请考虑这些业界公认的Juniper认证。每项证书都验证了实现和管理AI驱动无线网络的特定技能。","review.juniper-mist.jncia-mistai":"JNCIA-MistAI","review.juniper-mist.foundational.understanding.of.wlan.and":"对WLAN和Mist AI技术、特性和功能的基础理解。","review.juniper-mist.jncis-mistai.wireless":"JNCIS-MistAI无线","review.juniper-mist.advanced.wireless.implementation.with.mist":"使用Mist AI的高级无线实现，包括故障排除和优化。","review.juniper-mist.jncip-mistai":"JNCIP-MistAI","review.juniper-mist.professional-level.expertise.in.complex.mist":"复杂Mist AI部署和集成的专业级专业知识。","review.juniper-mist.final.verdict":"最终判决","review.juniper-mist.outstanding":"杰出的","review.juniper-mist.juniper.mist.ai.sets.the":"Juniper Mist AI为AI驱动的网络设定了标准。Marvis真正具有变革性——它改变了网络团队的日常运营方式。对用户体验（SLE）而不仅仅是基础设施指标的关注是令人耳目一新的。虽然纯云模式和高级定价不适合所有人，但对于采用它的组织来说，Mist提供了卓越的价值。","review.juniper-mist.ai.capabilities":"AI功能","review.juniper-mist.user.experience":"用户体验","review.juniper-mist.wireless":"无线","review.juniper-mist.value.for.money":"性价比","review.juniper-mist.ecosystem":"生态系统","review.juniper-mist.request.demo":"请求演示→","review.juniper-mist.compare.alternatives":"比较替代方案","review.common.screenshots.interface":"屏幕截图&amp;界面","review.juniper-mist.explore.juniper.mist.ai-driven.networking":"探索Juniper Mist AI驱动的网络：","review.juniper-mist.frequently.asked.questions":"常见问题","review.juniper-mist.faq.q1":"Mist可以离线工作吗?","review.juniper-mist.faq.a1":"如果云连接丢失，网络本身将继续运行——AP和交换机将使用缓存的策略运行。但是，AI功能、管理和Marvis需要云连接。没有本地部署选项。","review.juniper-mist.faq.q2":"Marvis与Cisco AI相比如何?","review.juniper-mist.faq.a2":"Marvis通常被认为在对话式故障排除和自然语言查询方面更先进。Cisco DNA Center AI在复杂的Cisco环境中的自动化修复方面更强大。Marvis在用户体验方面获胜；Cisco在集成深度方面获胜。","review.juniper-mist.faq.q3":"我需要Juniper交换机才能使用Mist吗?","review.juniper-mist.faq.a3":"不，Mist无线网络可与任何交换机基础设施配合使用。但是，要获得完整的\"有线保证\"AI功能和Marvis对有线网络的可见性，您需要通过Mist管理的Juniper EX交换机。","review.juniper-mist.faq.q4":"数据主权怎么样?","review.juniper-mist.faq.a4":"Mist提供区域云实例（美国、欧盟、亚太）以满足数据主权要求。您的网络数据将保留在选定的区域内。对于高度受管制的行业，请与Juniper讨论具体的合规性需求。"},
    ja: {"nav.guides":"ガイド","nav.compare":"比較","nav.about":"について","review.juniper-mist.overview":"概要","review.juniper-mist.juniper.mist.ai.represents.a":"Juniper Mist AIはネットワーク管理への根本的に異なるアプローチを表しています。既存製品にAI機能を追加した従来のベンダーとは異なり、MistはAIネイティブプラットフォームとして最初から構築されました。2019年にJuniper Networksに買収されたMistは、Juniperの企業向けAI駆動戦略の基礎となっています。","review.juniper-mist.the.platforms.crown.jewel.is":"プラットフォームの目玉はMarvis—自然言語処理を使って質問に答え、問題をトラブルシューティングし、洞察を提供する仮想ネットワークアシスタントです。ダッシュボードとログを掘り下げる代わりに、\"会議室のWiFiが遅いのはなぜですか？\" とMarvisに尋ねるだけで、実行可能な答えが得られます。","review.juniper-mist.mist.covers.the.full.network":"Mistは完全なネットワークスタックをカバーしています：ワイヤレス（Wi-Fi 6/6E）、有線スイッチング、およびSD-WAN。クラウドネイティブアーキテクチャは、配置するコントローラーがないことを意味します—すべては単一のクラウドポータルを通じて管理され、AIはネットワークデータを継続的に分析します。","review.juniper-mist.meet.marvis.your.ai.network":"Marvisをご紹介：AIネットワークアシスタント","review.juniper-mist.why.are.users.in.building":"\"A棟のユーザーがビデオ通話について不平を言うのはなぜですか?\" Marvisはデータを分析して対応します：\"A棟の3つのAPがビデオ通話中に高いチャネル利用率を経験しています。推奨される操作：バンドステアリングを有効にして、会議室2にAPを追加します。\"","review.juniper-mist.key.features":"主な機能","review.juniper-mist.conversational.troubleshooting.with.natural.language":"自然言語によるトラブルシューティング対話。平易な英語で質問し、ネットワーク問題についてのインテリジェントで文脈を認識した回答を取得します。","review.juniper-mist.automated.network.optimization.without.human":"人的介入のない自動ネットワーク最適化。AIはRF設定を継続的に調整し、問題を識別し、修復を推奨します。","review.juniper-mist.sle.dashboards.measure.actual.user":"SLEダッシュボードは実際のユーザー体験を測定します。インフラストラクチャメトリクスだけではなく、接続時間、スループット、カバレッジ、およびアプリケーションパフォーマンスを追跡します。","review.juniper-mist.marvis.automatically.correlates.events.across":"Marvisはネットワーク全体のイベントを自動的に関連付けて、根本原因を特定します。手動ログ分析や推測はもう不要です。","review.juniper-mist.ai-driven.wireless.optimization.including.dynamic":"AI駆動のワイヤレス最適化：動的チャネルと電力管理、クライアントステアリング、干渉軽減を含みます。","review.juniper-mist.extend.ai.insights.to.sd-wan":"AI洞察をSD-WAN配置に拡張します。Marvisは回線の健全性、アプリケーションパフォーマンスを監視し、問題の周りで自動的にルーティングします。","review.juniper-mist.patented.vble.virtual.bluetooth.le":"屋内位置特定用の特許取得済みvBLE（仮想Bluetooth LE）技術。ウェイファインディング、資産追跡、位置分析を有効にします。","review.juniper-mist.100.cloud-managed.with.no.controllers":"100%クラウド管理で、配置するコントローラーはありません。更新は自動的に行われ、AIモデルはグローバル学習により継続的に改善されます。","review.juniper-mist.pros.cons":"長所&amp;短所","review.juniper-mist.advantages":"長所","review.juniper-mist.marvis.ai.is.truly.revolutionary":"Marvis AIは真に革新的です","review.juniper-mist.best-in-class.user.experience.metrics.sles":"一流のユーザー体験メトリクス（SLE）","review.juniper-mist.100.cloud.no.on-premise":"100%クラウド—オンプレミスコントローラーなし","review.juniper-mist.conversational.troubleshooting.saves.hours":"会話型トラブルシューティングで時間を節約","review.juniper-mist.excellent.wireless.performance":"優れたワイヤレスパフォーマンス","review.juniper-mist.strong.sd-wan.integration":"強力なSD-WAN統合","review.juniper-mist.built-in.location.services":"組み込み位置情報サービス","review.juniper-mist.modern.intuitive.ui":"モダンで直感的なUI","review.juniper-mist.api-first.architecture":"APIファースト・アーキテクチャ","review.juniper-mist.continuous.ai.improvement":"AI継続的改善","review.juniper-mist.disadvantages":"短所","review.juniper-mist.cloud-only.no.on-premise.option":"クラウドのみ（オンプレミスオプションなし）","review.juniper-mist.premium.pricing.vs.traditional.vendors":"従来のベンダーと比較してのプレミアム価格","review.juniper-mist.juniper.switching.ecosystem.less.mature":"Juniperスイッチング生態系は成熟度が低い","review.juniper-mist.requires.cloud.connectivity":"クラウド接続が必要","review.juniper-mist.smaller.partner.ecosystem.than.cisco":"Ciscoより小さいパートナー生態系","review.juniper-mist.complex.licensing.structure":"複雑なライセンス構造","review.juniper-mist.limited.legacy.device.support":"レガシーデバイスのサポート限定","review.juniper-mist.learning.curve.for.marvis.queries":"Marvisクエリの学習曲線","review.juniper-mist.pricing":"価格","review.juniper-mist.mist.ai.uses.subscription.licensing":"Mist AIはデバイス数と機能層に基づくサブスクリプションライセンスを使用します。すべてのライセンスにはクラウド管理とAI機能が含まれます—別途購入する\"AI アドオン\" はありません。","review.juniper-mist.wi-fi.assurance.150-200apyear.includes.marvis":"Wi-Fiアシュアランス：~$150-200/AP/年（ワイヤレスMarvis含む）","review.juniper-mist.wired.assurance.50-100switchyear.adds.marvis":"有線アシュアランス：~$50-100/スイッチ/年（有線Marvis追加）","review.juniper-mist.wan.assurance.100-200edgeyear.sd-wan.with":"WANアシュアランス：~$100-200/エッジ/年（Marvis付きSD-WAN）","review.juniper-mist.premium.analytics.30-50useryear.advanced.location":"プレミアムアナリティクス：~$30-50/ユーザー/年（高度な位置情報サービス）","review.juniper-mist.pricing.varies.based.on.term":"価格は契約期間（1、3、または5年）と数量によって異なります。正確な見積もりについてはJuniperまたはパートナーにお問い合わせください。","review.juniper-mist.best.use.cases":"最適なユースケース","review.juniper-mist.cloud-first.organizations":"クラウドファースト・オーガニゼーション","review.juniper-mist.location.services.analytics":"位置情報サービス+分析","review.juniper-mist.asset.tracking.reliability":"資産追跡+信頼性","review.juniper-mist.high-density.wi-fi.sles":"高密度Wi-Fi + SLE","review.juniper-mist.guest.experience.wayfinding":"ゲスト体験+ウェイファインディング","review.juniper-mist.iot.location.intelligence":"IoT+位置情報インテリジェンス","review.juniper-mist.recommended.certifications":"推奨認定資格","review.juniper-mist.to.maximize.the.value.of":"Juniper Mist AIの価値を最大化し、ワイヤレスネットワーク職を進めるために、業界で認識されているJuniper認定を検討してください。各認定資格は、AI駆動のワイヤレスネットワークを実装および管理するための特定のスキルを検証します。","review.juniper-mist.jncia-mistai":"JNCIA-MistAI","review.juniper-mist.foundational.understanding.of.wlan.and":"WLANおよびMist AI技術、機能、および機能についての基本的な理解。","review.juniper-mist.jncis-mistai.wireless":"JNCIS-MistAI ワイヤレス","review.juniper-mist.advanced.wireless.implementation.with.mist":"Mist AIを使用した高度なワイヤレス実装：トラブルシューティングと最適化を含む。","review.juniper-mist.jncip-mistai":"JNCIP-MistAI","review.juniper-mist.professional-level.expertise.in.complex.mist":"複雑なMist AI展開と統合に関する専門家レベルの専門知識。","review.juniper-mist.final.verdict":"最終判定","review.juniper-mist.outstanding":"傑出した","review.juniper-mist.juniper.mist.ai.sets.the":"Juniper Mist AIはAI駆動ネットワークの標準を設定します。Marvisは真に変革的です—ネットワークチームの日常的な運用方法を変えます。インフラストラクチャメトリクスだけでなく、ユーザー体験（SLE）に焦点を当てることは新鮮です。クラウドのみのモデルとプレミアム価格設定は万能ではありませんが、それを採用する組織にとって、Mistは卓越した価値を提供します。","review.juniper-mist.ai.capabilities":"AI機能","review.juniper-mist.user.experience":"ユーザー体験","review.juniper-mist.wireless":"ワイヤレス","review.juniper-mist.value.for.money":"コストパフォーマンス","review.juniper-mist.ecosystem":"エコシステム","review.juniper-mist.request.demo":"デモを要求→","review.juniper-mist.compare.alternatives":"代替案を比較","review.common.screenshots.interface":"スクリーンショット&amp;インターフェース","review.juniper-mist.explore.juniper.mist.ai-driven.networking":"Juniper Mist AI駆動ネットワークを探索：","review.juniper-mist.frequently.asked.questions":"よくある質問","review.juniper-mist.faq.q1":"Mistはオフラインで動作できますか?","review.juniper-mist.faq.a1":"クラウド接続が失われた場合、ネットワーク自体は機能し続けます。APとスイッチはキャッシュされたポリシーを使用して動作します。ただし、AI機能、管理、およびMarvisはクラウド接続が必要です。オンプレミスの展開オプションはありません。","review.juniper-mist.faq.q2":"MarvisはCisco AIとどのように比較されますか?","review.juniper-mist.faq.a2":"Marvisは一般的に、会話型トラブルシューティングと自然言語クエリの方がより高度と考えられています。Cisco DNA Center AIは、複雑なCisco環境での自動修復に強みがあります。Marvisはユーザーエクスペリエンスで勝利し、Ciscoは統合の深さで勝利します。","review.juniper-mist.faq.q3":"MistにJuniperスイッチが必要ですか?","review.juniper-mist.faq.a3":"いいえ、Mistワイヤレスは任意のスイッチインフラストラクチャで動作します。ただし、完全な「有線保証」AI機能とMarvisの有線ネットワークへの可視性を取得するには、Mistを通じて管理されるJuniper EXスイッチが必要です。","review.juniper-mist.faq.q4":"データソブリンティについてはどうですか?","review.juniper-mist.faq.a4":"Mistは、データソブリンティの要件に対応するために地域クラウドインスタンス（米国、EU、APAC）を提供します。ネットワークデータは選択した地域内に保たれます。高度に規制された業界では、特定のコンプライアンス要件についてJuniperと相談してください。"},
    ko: {"nav.guides":"가이드","nav.compare":"비교","nav.about":"정보","review.juniper-mist.overview":"개요","review.juniper-mist.juniper.mist.ai.represents.a":"Juniper Mist AI는 네트워크 관리에 대한 근본적으로 다른 접근 방식을 나타냅니다. 기존 제품에 AI 기능을 추가한 전통적 벤더들과 달리 Mist는 AI 기반 플랫폼으로 처음부터 구축되었습니다. 2019년 Juniper Networks에 인수된 후 Mist는 Juniper의 AI 주도 엔터프라이즈 전략의 초석이 되었습니다.","review.juniper-mist.the.platforms.crown.jewel.is":"플랫폼의 보석은 Marvis입니다. 자연어 처리를 사용하여 질문에 답하고 문제를 해결하며 인사이트를 제공하는 가상 네트워크 어시스턴트입니다. 대시보드와 로그를 뒤지는 대신 Marvis에게 \"컨퍼런스룸 WiFi가 느린 이유는?\"이라고 물어보고 실행 가능한 답변을 얻을 수 있습니다.","review.juniper-mist.mist.covers.the.full.network":"Mist는 전체 네트워크 스택을 커버합니다: 무선(Wi-Fi 6/6E), 유선 스위칭 및 SD-WAN. 클라우드 네이티브 아키텍처는 배포할 컨트롤러가 없다는 의미입니다. 모든 것이 단일 클라우드 포털을 통해 관리되며 AI가 지속적으로 네트워크 데이터를 분석합니다.","review.juniper-mist.meet.marvis.your.ai.network":"Marvis 소개: AI 네트워크 어시스턴트","review.juniper-mist.why.are.users.in.building":"\"Building A의 사용자들이 화상통화에 대해 불평하는 이유는?\" Marvis가 데이터를 분석하고 응답합니다: \"Building A의 3개 AP가 화상통화 중 높은 채널 이용률을 경험하고 있습니다. 제안 조치: 대역 스티어링을 활성화하고 Conference Room 2에 AP를 추가하세요.\"","review.juniper-mist.key.features":"주요 기능","review.juniper-mist.conversational.troubleshooting.with.natural.language":"자연어를 사용한 대화형 문제 해결. 일반 영어로 질문을 하고 네트워크 문제에 대한 지능형 상황 인식 답변을 받습니다.","review.juniper-mist.automated.network.optimization.without.human":"인간 개입 없이 자동화된 네트워크 최적화. AI가 지속적으로 RF 설정을 조정하고 문제를 식별하며 해결 방법을 권장합니다.","review.juniper-mist.sle.dashboards.measure.actual.user":"SLE 대시보드는 인프라 메트릭뿐만 아니라 실제 사용자 경험을 측정합니다. 연결 시간, 처리량, 커버리지 및 애플리케이션 성능을 추적합니다.","review.juniper-mist.marvis.automatically.correlates.events.across":"Marvis는 네트워크 전체의 이벤트를 자동으로 상관관계 지어 근본 원인을 파악합니다. 더 이상 수동 로그 분석이나 추측이 없습니다.","review.juniper-mist.ai-driven.wireless.optimization.including.dynamic":"동적 채널 및 전력 관리, 클라이언트 스티어링 및 간섭 완화를 포함한 AI 기반 무선 최적화.","review.juniper-mist.extend.ai.insights.to.sd-wan":"AI 인사이트를 SD-WAN 배포로 확장합니다. Marvis는 회로 상태, 애플리케이션 성능을 모니터링하고 자동으로 문제를 우회합니다.","review.juniper-mist.patented.vble.virtual.bluetooth.le":"실내 위치 지정을 위한 특허 보유 vBLE(가상 Bluetooth LE) 기술. 웨이파인딩, 자산 추적 및 위치 분석을 활성화합니다.","review.juniper-mist.100.cloud-managed.with.no.controllers":"100% 클라우드 관리, 배포할 컨트롤러 없음. 업데이트는 자동으로 발생하고 AI 모델은 글로벌 학습으로 지속적으로 개선됩니다.","review.juniper-mist.pros.cons":"장점 및 단점","review.juniper-mist.advantages":"장점","review.juniper-mist.marvis.ai.is.truly.revolutionary":"Marvis AI는 진정으로 혁신적입니다","review.juniper-mist.best-in-class.user.experience.metrics.sles":"동급 최고의 사용자 경험 메트릭(SLEs)","review.juniper-mist.100.cloud.no.on-premise":"100% 클라우드 - 온프레미스 컨트롤러 없음","review.juniper-mist.conversational.troubleshooting.saves.hours":"대화형 문제 해결로 시간 절약","review.juniper-mist.excellent.wireless.performance":"우수한 무선 성능","review.juniper-mist.strong.sd-wan.integration":"강력한 SD-WAN 통합","review.juniper-mist.built-in.location.services":"내장된 위치 서비스","review.juniper-mist.modern.intuitive.ui":"현대적이고 직관적인 UI","review.juniper-mist.api-first.architecture":"API 우선 아키텍처","review.juniper-mist.continuous.ai.improvement":"지속적인 AI 개선","review.juniper-mist.disadvantages":"단점","review.juniper-mist.cloud-only.no.on-premise.option":"클라우드 전용(온프레미스 옵션 없음)","review.juniper-mist.premium.pricing.vs.traditional.vendors":"기존 벤더 대비 프리미엄 가격","review.juniper-mist.juniper.switching.ecosystem.less.mature":"Juniper 스위칭 생태계가 덜 성숙함","review.juniper-mist.requires.cloud.connectivity":"클라우드 연결 필요","review.juniper-mist.smaller.partner.ecosystem.than.cisco":"Cisco보다 작은 파트너 생태계","review.juniper-mist.complex.licensing.structure":"복잡한 라이선싱 구조","review.juniper-mist.limited.legacy.device.support":"제한된 레거시 장치 지원","review.juniper-mist.learning.curve.for.marvis.queries":"Marvis 쿼리의 학습 곡선","review.juniper-mist.pricing":"가격","review.juniper-mist.mist.ai.uses.subscription.licensing":"Mist AI는 장치 수 및 기능 계층을 기반으로 한 구독 라이선싱을 사용합니다. 모든 라이선스에는 클라우드 관리 및 AI 기능이 포함되며 별도로 구매할 수 있는 \"AI 애드온\"은 없습니다.","review.juniper-mist.wi-fi.assurance.150-200apyear.includes.marvis":"Wi-Fi Assurance: 약 $150-200/AP/년 (무선용 Marvis 포함)","review.juniper-mist.wired.assurance.50-100switchyear.adds.marvis":"Wired Assurance: 약 $50-100/스위치/년 (유선용 Marvis 추가)","review.juniper-mist.wan.assurance.100-200edgeyear.sd-wan.with":"WAN Assurance: 약 $100-200/엣지/년 (Marvis가 있는 SD-WAN)","review.juniper-mist.premium.analytics.30-50useryear.advanced.location":"Premium Analytics: 약 $30-50/사용자/년 (고급 위치 서비스)","review.juniper-mist.pricing.varies.based.on.term":"가격은 약정 기간(1, 3 또는 5년) 및 볼륨에 따라 다릅니다. 정확한 견적은 Juniper 또는 파트너에 문의하세요.","review.juniper-mist.best.use.cases":"최적 사용 사례","review.juniper-mist.cloud-first.organizations":"클라우드 우선 조직","review.juniper-mist.location.services.analytics":"위치 서비스 + 분석","review.juniper-mist.asset.tracking.reliability":"자산 추적 + 신뢰성","review.juniper-mist.high-density.wi-fi.sles":"고밀도 Wi-Fi + SLEs","review.juniper-mist.guest.experience.wayfinding":"게스트 경험 + 웨이파인딩","review.juniper-mist.iot.location.intelligence":"IoT + 위치 인텔리전스","review.juniper-mist.recommended.certifications":"권장 인증","review.juniper-mist.to.maximize.the.value.of":"Juniper Mist AI의 가치를 최대화하고 무선 네트워킹 경력을 발전시키려면 이러한 업계 인정 Juniper 인증을 고려하세요. 각 자격증은 AI 기반 무선 네트워크 구현 및 관리를 위한 특정 기술을 검증합니다.","review.juniper-mist.jncia-mistai":"JNCIA-MistAI","review.juniper-mist.foundational.understanding.of.wlan.and":"WLAN 및 Mist AI 기술, 기능 및 기능에 대한 기초적 이해.","review.juniper-mist.jncis-mistai.wireless":"JNCIS-MistAI Wireless","review.juniper-mist.advanced.wireless.implementation.with.mist":"Mist AI를 사용한 고급 무선 구현, 문제 해결 및 최적화 포함.","review.juniper-mist.jncip-mistai":"JNCIP-MistAI","review.juniper-mist.professional-level.expertise.in.complex.mist":"복잡한 Mist AI 배포 및 통합에 대한 전문가 수준의 전문 지식.","review.juniper-mist.final.verdict":"최종 평가","review.juniper-mist.outstanding":"탁월함","review.juniper-mist.juniper.mist.ai.sets.the":"Juniper Mist AI는 AI 기반 네트워킹의 표준을 설정합니다. Marvis는 진정으로 혁신적입니다. 네트워크 팀이 일상적으로 운영하는 방식을 변경합니다. 인프라 메트릭만이 아닌 사용자 경험(SLEs)에 초점을 맞추는 것은 신선합니다. 클라우드 전용 모델과 프리미엄 가격이 모든 사람에게 적합하지는 않지만, 이를 수용하는 조직의 경우 Mist는 탁월한 가치를 제공합니다.","review.juniper-mist.ai.capabilities":"AI 기능","review.juniper-mist.user.experience":"사용자 경험","review.juniper-mist.wireless":"무선","review.juniper-mist.value.for.money":"비용 대비 가치","review.juniper-mist.ecosystem":"생태계","review.juniper-mist.request.demo":"데모 요청 →","review.juniper-mist.compare.alternatives":"대안 비교","review.common.screenshots.interface":"스크린샷 및 인터페이스","review.juniper-mist.explore.juniper.mist.ai-driven.networking":"Juniper Mist AI 기반 네트워킹 탐색:","review.juniper-mist.frequently.asked.questions":"자주 묻는 질문","review.juniper-mist.faq.q1":"Mist가 오프라인에서 작동할 수 있습니까?","review.juniper-mist.faq.a1":"클라우드 연결이 끊어진 경우에도 네트워크 자체는 계속 작동합니다 — AP와 스위치는 캐시된 정책을 사용하여 작동합니다. 그러나 AI 기능, 관리 및 Marvis는 클라우드 연결이 필요합니다. 온프레미스 배포 옵션이 없습니다.","review.juniper-mist.faq.q2":"Marvis가 Cisco AI와 어떻게 비교합니까?","review.juniper-mist.faq.a2":"Marvis는 일반적으로 대화형 문제 해결 및 자연어 쿼리에 더 고급으로 간주됩니다. Cisco의 DNA Center AI는 복잡한 Cisco 환경에서 자동화된 수정에 더 강합니다. Marvis는 사용자 경험에서 우수하고 Cisco는 통합 깊이에서 우수합니다.","review.juniper-mist.faq.q3":"Mist를 위해 Juniper 스위치가 필요합니까?","review.juniper-mist.faq.a3":"아니오, Mist 무선은 모든 스위치 인프라와 함께 작동합니다. 그러나 전체 \"유선 보증\" AI 기능과 Marvis의 유선 네트워크에 대한 가시성을 얻으려면 Mist를 통해 관리되는 Juniper EX 스위치가 필요합니다.","review.juniper-mist.faq.q4":"데이터 주권에 대해서는 어떻습니까?","review.juniper-mist.faq.a4":"Mist는 데이터 주권 요구 사항을 해결하기 위해 지역별 클라우드 인스턴스(US, EU, APAC)를 제공합니다. 네트워크 데이터는 선택된 지역 내에 머물러 있습니다. 매우 규제가 심한 산업의 경우 Juniper에 특정 규정 준수 요구 사항을 논의하십시오."},
    ar: {"nav.guides":"الأدلة","nav.compare":"مقارنة","nav.about":"حول","review.juniper-mist.overview":"نظرة عامة","review.juniper-mist.juniper.mist.ai.represents.a":"يمثل Juniper Mist AI نهجاً مختلفاً بشكل جذري لإدارة الشبكات. بخلاف البائعين التقليديين الذين أضافوا ميزات الذكاء الاصطناعي إلى منتجات قائمة، تم بناء Mist من الألف إلى الياء كمنصة أصلية للذكاء الاصطناعي. بعد استحواذ Juniper Networks عليها في عام 2019، أصبحت Mist حجر الزاوية في استراتيجية Juniper الموجهة بالذكاء الاصطناعي للشركات.","review.juniper-mist.the.platforms.crown.jewel.is":"جوهرة المنصة هي Marvis، مساعد شبكة افتراضي يستخدم معالجة اللغات الطبيعية للإجابة على الأسئلة وحل المشاكل وتقديم الرؤى. بدلاً من البحث في لوحات المعلومات والسجلات، يمكنك ببساطة سؤال Marvis \"لماذا WiFi غرفة المؤتمرات بطيء؟\" والحصول على إجابة قابلة للتنفيذ.","review.juniper-mist.mist.covers.the.full.network":"تغطي Mist كامل مكدس الشبكة: اللاسلكية (Wi-Fi 6/6E)، والتحويل السلكي، و SD-WAN. تعني الهندسة المعمارية الأصلية للسحابة عدم وجود متحكمات للنشر - يتم إدارة كل شيء من خلال بوابة سحابة واحدة مع AI يحلل بيانات شبكتك بشكل مستمر.","review.juniper-mist.meet.marvis.your.ai.network":"تعريف Marvis: مساعد الشبكة المدعوم بالذكاء الاصطناعي","review.juniper-mist.why.are.users.in.building":"\"لماذا يشتكي المستخدمون في المبنى A من المكالمات الفيديوية؟\" يحلل Marvis البيانات ويرد: \"3 APs في المبنى A تواجه استخدام قنوات عالية أثناء المكالمات الفيديوية. الإجراء المقترح: تفعيل توجيه النطاق وإضافة AP في غرفة المؤتمرات 2.\"","review.juniper-mist.key.features":"الميزات الرئيسية","review.juniper-mist.conversational.troubleshooting.with.natural.language":"استكشاف الأخطاء والإصلاح التحاوري باستخدام اللغة الطبيعية. اطرح الأسئلة باللغة الإنجليزية العادية واحصل على إجابات ذكية وتدرك السياق حول مشاكل الشبكة.","review.juniper-mist.automated.network.optimization.without.human":"تحسين الشبكة الآلي دون تدخل بشري. يقوم الذكاء الاصطناعي بضبط إعدادات RF بشكل مستمر وتحديد المشاكل والتوصية بالعلاجات.","review.juniper-mist.sle.dashboards.measure.actual.user":"تقيس لوحات معلومات SLE تجربة المستخدم الفعلية وليس فقط مقاييس البنية التحتية. تتبع وقت الاتصال والإنتاجية والتغطية وأداء التطبيق.","review.juniper-mist.marvis.automatically.correlates.events.across":"يرتبط Marvis تلقائياً الأحداث عبر الشبكة لتحديد الأسباب الجذرية. لا مزيد من تحليل السجل اليدوي أو التخمين.","review.juniper-mist.ai-driven.wireless.optimization.including.dynamic":"تحسين اللاسلكية الموجه بالذكاء الاصطناعي بما في ذلك إدارة القنوات والطاقة الديناميكية، وتوجيه العميل، وتخفيف التداخل.","review.juniper-mist.extend.ai.insights.to.sd-wan":"توسيع رؤى الذكاء الاصطناعي لنشر SD-WAN. يراقب Marvis صحة الدائرة وأداء التطبيق ويوجه تلقائياً حول المشاكل.","review.juniper-mist.patented.vble.virtual.bluetooth.le":"تقنية vBLE (Bluetooth LE الافتراضية) المسجلة بموجب براءة اختراع للموضع الداخلي. تفعيل الملاحة والتتبع بالأصول وتحليلات الموقع.","review.juniper-mist.100.cloud-managed.with.no.controllers":"إدارة 100٪ سحابة بدون متحكمات للنشر. تحدث التحديثات تلقائياً وتتحسن نماذج الذكاء الاصطناعي بشكل مستمر من خلال التعلم العالمي.","review.juniper-mist.pros.cons":"الإيجابيات والسلبيات","review.juniper-mist.advantages":"المميزات","review.juniper-mist.marvis.ai.is.truly.revolutionary":"Marvis AI ثوري حقاً","review.juniper-mist.best-in-class.user.experience.metrics.sles":"أفضل مقاييس تجربة المستخدم في فئتها (SLEs)","review.juniper-mist.100.cloud.no.on-premise":"100٪ سحابة - بدون متحكمات في الموقع","review.juniper-mist.conversational.troubleshooting.saves.hours":"استكشاف الأخطاء والإصلاح التحاوري يوفر الساعات","review.juniper-mist.excellent.wireless.performance":"أداء لاسلكية ممتازة","review.juniper-mist.strong.sd-wan.integration":"تكامل SD-WAN قوي","review.juniper-mist.built-in.location.services":"خدمات الموقع المدمجة","review.juniper-mist.modern.intuitive.ui":"واجهة حديثة وبديهية","review.juniper-mist.api-first.architecture":"أولاً هندسة معمارية API","review.juniper-mist.continuous.ai.improvement":"تحسين الذكاء الاصطناعي المستمر","review.juniper-mist.disadvantages":"العيوب","review.juniper-mist.cloud-only.no.on-premise.option":"سحابة فقط (بدون خيار في الموقع)","review.juniper-mist.premium.pricing.vs.traditional.vendors":"تسعير متميز مقابل البائعين التقليديين","review.juniper-mist.juniper.switching.ecosystem.less.mature":"نظام Juniper للتبديل أقل نضجاً","review.juniper-mist.requires.cloud.connectivity":"يتطلب اتصال سحابة","review.juniper-mist.smaller.partner.ecosystem.than.cisco":"نظام بيئي شريك أصغر من Cisco","review.juniper-mist.complex.licensing.structure":"هيكل ترخيص معقد","review.juniper-mist.limited.legacy.device.support":"دعم جهاز وراثي محدود","review.juniper-mist.learning.curve.for.marvis.queries":"منحنى التعلم لاستعلامات Marvis","review.juniper-mist.pricing":"التسعير","review.juniper-mist.mist.ai.uses.subscription.licensing":"يستخدم Mist AI ترخيص الاشتراك على أساس عدد الأجهزة وطبقات الميزات. تتضمن جميع التراخيص إدارة السحابة وميزات الذكاء الاصطناعي - لا يوجد \"وظيفة إضافية للذكاء الاصطناعي\" للشراء بشكل منفصل.","review.juniper-mist.wi-fi.assurance.150-200apyear.includes.marvis":"Wi-Fi Assurance: حوالي $150-200/AP/السنة (يشمل Marvis للاسلكية)","review.juniper-mist.wired.assurance.50-100switchyear.adds.marvis":"Wired Assurance: حوالي $50-100/الكاتب/السنة (يضيف Marvis للسلكي)","review.juniper-mist.wan.assurance.100-200edgeyear.sd-wan.with":"WAN Assurance: حوالي $100-200/edge/السنة (SD-WAN مع Marvis)","review.juniper-mist.premium.analytics.30-50useryear.advanced.location":"Premium Analytics: حوالي $30-50/المستخدم/السنة (خدمات الموقع المتقدمة)","review.juniper-mist.pricing.varies.based.on.term":"يختلف السعر حسب طول المدة (1 أو 3 أو 5 سنوات) والحجم. اتصل بـ Juniper أو شريك للحصول على عروض أسعار دقيقة.","review.juniper-mist.best.use.cases":"أفضل حالات الاستخدام","review.juniper-mist.cloud-first.organizations":"منظمات أولاً سحابة","review.juniper-mist.location.services.analytics":"خدمات الموقع + التحليلات","review.juniper-mist.asset.tracking.reliability":"تتبع الأصول + الموثوقية","review.juniper-mist.high-density.wi-fi.sles":"عالية الكثافة Wi-Fi + SLEs","review.juniper-mist.guest.experience.wayfinding":"تجربة الضيف + الملاحة","review.juniper-mist.iot.location.intelligence":"IoT + استخبارات الموقع","review.juniper-mist.recommended.certifications":"الشهادات الموصى بها","review.juniper-mist.to.maximize.the.value.of":"لتعظيم قيمة Juniper Mist AI والتقدم في مسيرتك المهنية في الشبكات اللاسلكية، فكر في شهادات Juniper المعترف بها من الصناعة هذه. تتحقق كل بيانات الاعتماد من مهارات محددة لتنفيذ وإدارة شبكات لاسلكية موجهة بالذكاء الاصطناعي.","review.juniper-mist.jncia-mistai":"JNCIA-MistAI","review.juniper-mist.foundational.understanding.of.wlan.and":"الفهم الأساسي لتكنولوجيا WLAN و Mist AI والميزات والوظائف.","review.juniper-mist.jncis-mistai.wireless":"JNCIS-MistAI Wireless","review.juniper-mist.advanced.wireless.implementation.with.mist":"تنفيذ لاسلكي متقدم مع Mist AI، بما في ذلك استكشاف الأخطاء والتحسين.","review.juniper-mist.jncip-mistai":"JNCIP-MistAI","review.juniper-mist.professional-level.expertise.in.complex.mist":"خبرة على مستوى احترافي في عمليات نشر واتصالات Mist AI المعقدة.","review.juniper-mist.final.verdict":"الحكم النهائي","review.juniper-mist.outstanding":"متميز","review.juniper-mist.juniper.mist.ai.sets.the":"يحدد Juniper Mist AI معيار الشبكات الموجهة بالذكاء الاصطناعي. Marvis تحويلية بحق - فهي تغير الطريقة التي تعمل بها فرق الشبكة يومياً. التركيز على تجربة المستخدم (SLEs) بدلاً من مقاييس البنية التحتية فقط منعش. في حين أن نموذج السحابة فقط والتسعير المتميز لن يناسب الجميع، بالنسبة للمنظمات التي تعتنقها، توفر Mist قيمة استثنائية.","review.juniper-mist.ai.capabilities":"القدرات الاصطناعية","review.juniper-mist.user.experience":"تجربة المستخدم","review.juniper-mist.wireless":"لاسلكي","review.juniper-mist.value.for.money":"قيمة الأموال","review.juniper-mist.ecosystem":"النظام البيئي","review.juniper-mist.request.demo":"طلب عرض توضيحي →","review.juniper-mist.compare.alternatives":"مقارنة البدائل","review.common.screenshots.interface":"لقطات الشاشة والواجهة","review.juniper-mist.explore.juniper.mist.ai-driven.networking":"استكشف شبكات Juniper Mist الموجهة بالذكاء الاصطناعي:","review.juniper-mist.frequently.asked.questions":"الأسئلة الشائعة","review.juniper-mist.faq.q1":"هل يمكن لـ Mist أن تعمل في وضع عدم الاتصال؟","review.juniper-mist.faq.a1":"تستمر الشبكة نفسها في العمل إذا فُقد الاتصال بالسحابة — ستعمل أجهزة AP والمفاتيح باستخدام السياسات المخزنة مؤقتاً. ومع ذلك، تتطلب ميزات AI والإدارة وـ Marvis الاتصال بالسحابة. لا يوجد خيار نشر في الموقع.","review.juniper-mist.faq.q2":"كيف تقارن Marvis بـ Cisco AI؟","review.juniper-mist.faq.a2":"تُعتبر Marvis بشكل عام أكثر تقدماً للاستكشاف التفاعلي للأخطاء والاستعلامات باللغة الطبيعية. يتمتع Cisco DNA Center AI بقوة أكبر في إصلاح المشاكل الآلي في بيئات Cisco المعقدة. تفوز Marvis في تجربة المستخدم؛ Cisco تفوز في عمق التكامل.","review.juniper-mist.faq.q3":"هل أحتاج إلى مفاتيح Juniper لـ Mist؟","review.juniper-mist.faq.a3":"لا، تعمل Mist اللاسلكية مع أي بنية تحتية للمفاتيح. ومع ذلك، للحصول على ميزات \"ضمان السلك\" الكاملة لـ AI والرؤية من Marvis في الشبكة السلكية، تحتاج إلى مفاتيح Juniper EX مُدارة عبر Mist.","review.juniper-mist.faq.q4":"ماذا عن سيادة البيانات؟","review.juniper-mist.faq.a4":"توفر Mist نوى سحابة إقليمية (US, EU, APAC) لمعالجة متطلبات سيادة البيانات. بيانات الشبكة الخاصة بك تبقى داخل المنطقة المحددة. بالنسبة للصناعات المنظمة بشدة، ناقش احتياجات الامتثال المحددة مع Juniper."},
    hi: {"nav.guides":"गाइड","nav.compare":"तुलना","nav.about":"परिचय","review.juniper-mist.overview":"अवलोकन","review.juniper-mist.juniper.mist.ai.represents.a":"Juniper Mist AI नेटवर्क प्रबंधन के लिए एक मौलिक रूप से अलग दृष्टिकोण का प्रतिनिधित्व करता है। पारंपरिक विक्रेताओं के विपरीत जिन्होंने मौजूदा उत्पादों में AI सुविधाओं को जोड़ा, Mist को शुरुआत से ही एक AI-नेटिव प्लेटफॉर्म के रूप में बनाया गया था। 2019 में Juniper Networks द्वारा अधिग्रहित, Mist Juniper की AI-संचालित एंटरप्राइज़ रणनीति की आधारशिला बन गया है।","review.juniper-mist.the.platforms.crown.jewel.is":"प्लेटफॉर्म का मुकुट रत्न Marvis है - एक आभासी नेटवर्क सहायक जो प्रश्नों का उत्तर देने, समस्याओं का समाधान करने और अंतर्दृष्टि प्रदान करने के लिए प्राकृतिक भाषा प्रसंस्करण का उपयोग करता है। डैशबोर्ड और लॉग के माध्यम से खोदना के बजाय, आप बस Marvis से पूछ सकते हैं \"सम्मेलन कक्ष WiFi धीमा क्यों है?\" और कार्यकारी उत्तर प्राप्त करें।","review.juniper-mist.mist.covers.the.full.network":"Mist पूरे नेटवर्क स्टैक को कवर करता है: वायरलेस (Wi-Fi 6/6E), वायर्ड स्विचिंग और SD-WAN। इसकी क्लाउड-मूल आर्किटेक्चर का मतलब है कि तैनात करने के लिए कोई कंट्रोलर नहीं - सब कुछ एक एकल क्लाउड पोर्टल के माध्यम से प्रबंधित किया जाता है जिसमें AI लगातार आपके नेटवर्क डेटा का विश्लेषण करता है।","review.juniper-mist.meet.marvis.your.ai.network":"Marvis से मिलिए: आपका AI नेटवर्क सहायक","review.juniper-mist.why.are.users.in.building":"\"Building A के उपयोगकर्ता वीडियो कॉल के बारे में शिकायत क्यों कर रहे हैं?\" Marvis डेटा का विश्लेषण करता है और उत्तर देता है: \"Building A में 3 APs वीडियो कॉल के दौरान उच्च चैनल उपयोग का अनुभव कर रहे हैं। सुझाया गया कार्य: बैंड स्टीयरिंग सक्षम करें और सम्मेलन कक्ष 2 में AP जोड़ें।\"","review.juniper-mist.key.features":"मुख्य विशेषताएं","review.juniper-mist.conversational.troubleshooting.with.natural.language":"प्राकृतिक भाषा के साथ संवादात्मक समस्या निवारण। सामान्य अंग्रेजी में प्रश्न पूछें और नेटवर्क समस्याओं के बारे में बुद्धिमान, संदर्भ-जागरूक उत्तर प्राप्त करें।","review.juniper-mist.automated.network.optimization.without.human":"मानव हस्तक्षेप के बिना स्वचालित नेटवर्क अनुकूलन। AI लगातार RF सेटिंग्स समायोजित करता है, समस्याओं की पहचान करता है और सुधार की सिफारिश करता है।","review.juniper-mist.sle.dashboards.measure.actual.user":"SLE डैशबोर्ड वास्तविक उपयोगकर्ता अनुभव को मापते हैं, सिर्फ बुनियादी ढांचे के मेट्रिक्स नहीं। कनेक्ट करने का समय, थ्रूपुट, कवरेज और एप्लिकेशन प्रदर्शन ट्रैक करें।","review.juniper-mist.marvis.automatically.correlates.events.across":"Marvis स्वचालित रूप से नेटवर्क में घटनाओं को जड़ कारणों की पहचान करने के लिए सहसंबंधित करता है। अब कोई मैनुअल लॉग विश्लेषण या अनुमान नहीं है।","review.juniper-mist.ai-driven.wireless.optimization.including.dynamic":"गतिशील चैनल और शक्ति प्रबंधन, क्लाइंट स्टीयरिंग और हस्तक्षेप शमन सहित AI-संचालित वायरलेस अनुकूलन।","review.juniper-mist.extend.ai.insights.to.sd-wan":"SD-WAN तैनाती के लिए AI अंतर्दृष्टि विस्तारित करें। Marvis सर्किट स्वास्थ्य, एप्लिकेशन प्रदर्शन की निगरानी करता है और स्वचालित रूप से समस्याओं के चारों ओर मार्ग निर्धारित करता है।","review.juniper-mist.patented.vble.virtual.bluetooth.le":"इनडोर पोजिशनिंग के लिए पेटेंट vBLE (वर्चुअल Bluetooth LE) तकनीक। वेफाइंडिंग, एसेट ट्रैकिंग और स्थान विश्लेषण सक्षम करें।","review.juniper-mist.100.cloud-managed.with.no.controllers":"100% क्लाउड-प्रबंधित तैनात करने के लिए कोई नियंत्रक के साथ। अपडेट स्वचालित रूप से होते हैं, और AI मॉडल वैश्विक सीखने के साथ लगातार सुधार करते हैं।","review.juniper-mist.pros.cons":"पेशेवर और विपक्ष","review.juniper-mist.advantages":"फायदे","review.juniper-mist.marvis.ai.is.truly.revolutionary":"Marvis AI वास्तव में क्रांतिकारी है","review.juniper-mist.best-in-class.user.experience.metrics.sles":"सर्वश्रेष्ठ सापेक्ष उपयोगकर्ता अनुभव मेट्रिक्स (SLEs)","review.juniper-mist.100.cloud.no.on-premise":"100% क्लाउड - कोई ऑन-प्रिमाइसेस नियंत्रक नहीं","review.juniper-mist.conversational.troubleshooting.saves.hours":"संवादात्मक समस्या निवारण घंटे बचाता है","review.juniper-mist.excellent.wireless.performance":"उत्कृष्ट वायरलेस प्रदर्शन","review.juniper-mist.strong.sd-wan.integration":"मजबूत SD-WAN एकीकरण","review.juniper-mist.built-in.location.services":"अंतर्निहित स्थान सेवाएं","review.juniper-mist.modern.intuitive.ui":"आधुनिक, सहज UI","review.juniper-mist.api-first.architecture":"API-प्रथम आर्किटेक्चर","review.juniper-mist.continuous.ai.improvement":"सतत AI सुधार","review.juniper-mist.disadvantages":"नुकसान","review.juniper-mist.cloud-only.no.on-premise.option":"केवल क्लाउड (ऑन-प्रिमाइसेस विकल्प नहीं)","review.juniper-mist.premium.pricing.vs.traditional.vendors":"पारंपरिक विक्रेताओं बनाम प्रीमियम मूल्य","review.juniper-mist.juniper.switching.ecosystem.less.mature":"Juniper स्विचिंग इकोसिस्टम कम परिपक्व","review.juniper-mist.requires.cloud.connectivity":"क्लाउड कनेक्टिविटी की आवश्यकता है","review.juniper-mist.smaller.partner.ecosystem.than.cisco":"Cisco की तुलना में छोटा भागीदार पारिस्थितिकी तंत्र","review.juniper-mist.complex.licensing.structure":"जटिल लाइसेंसिंग संरचना","review.juniper-mist.limited.legacy.device.support":"सीमित विरासत उपकरण समर्थन","review.juniper-mist.learning.curve.for.marvis.queries":"Marvis प्रश्नों के लिए सीखने की अवस्था","review.juniper-mist.pricing":"कीमत","review.juniper-mist.mist.ai.uses.subscription.licensing":"Mist AI डिवाइस गणना और सुविधा स्तरों के आधार पर सदस्यता लाइसेंसिंग का उपयोग करता है। सभी लाइसेंस में क्लाउड प्रबंधन और AI सुविधाएं शामिल हैं - अलग से खरीदने के लिए कोई \"AI ऐड-ऑन\" नहीं है।","review.juniper-mist.wi-fi.assurance.150-200apyear.includes.marvis":"Wi-Fi Assurance: लगभग $150-200/AP/वर्ष (वायरलेस के लिए Marvis शामिल)","review.juniper-mist.wired.assurance.50-100switchyear.adds.marvis":"Wired Assurance: लगभग $50-100/स्विच/वर्ष (वायर्ड के लिए Marvis जोड़ता है)","review.juniper-mist.wan.assurance.100-200edgeyear.sd-wan.with":"WAN Assurance: लगभग $100-200/edge/वर्ष (Marvis के साथ SD-WAN)","review.juniper-mist.premium.analytics.30-50useryear.advanced.location":"Premium Analytics: लगभग $30-50/उपयोगकर्ता/वर्ष (उन्नत स्थान सेवाएं)","review.juniper-mist.pricing.varies.based.on.term":"कीमत अवधि की लंबाई (1, 3 या 5 वर्ष) और मात्रा के आधार पर भिन्न होती है। सटीक उद्धरणों के लिए Juniper या एक भागीदार से संपर्क करें।","review.juniper-mist.best.use.cases":"सर्वश्रेष्ठ उपयोग के मामले","review.juniper-mist.cloud-first.organizations":"क्लाउड-प्रथम संगठन","review.juniper-mist.location.services.analytics":"स्थान सेवाएं + विश्लेषण","review.juniper-mist.asset.tracking.reliability":"संपत्ति ट्रैकिंग + विश्वसनीयता","review.juniper-mist.high-density.wi-fi.sles":"उच्च-घनत्व Wi-Fi + SLEs","review.juniper-mist.guest.experience.wayfinding":"अतिथि अनुभव + वेफाइंडिंग","review.juniper-mist.iot.location.intelligence":"IoT + स्थान बुद्धिमत्ता","review.juniper-mist.recommended.certifications":"अनुशंसित प्रमाणपत्र","review.juniper-mist.to.maximize.the.value.of":"Juniper Mist AI के मूल्य को अधिकतम करने और अपने वायरलेस नेटवर्किंग कैरियर को आगे बढ़ाने के लिए, इन उद्योग-मान्यता प्राप्त Juniper प्रमाणपत्रों पर विचार करें। प्रत्येक क्रेडेंशियल AI-संचालित वायरलेस नेटवर्क को लागू करने और प्रबंधित करने के लिए विशिष्ट कौशल को मान्य करता है।","review.juniper-mist.jncia-mistai":"JNCIA-MistAI","review.juniper-mist.foundational.understanding.of.wlan.and":"WLAN और Mist AI तकनीक, सुविधाओं और कार्यक्षमता की मौलिक समझ।","review.juniper-mist.jncis-mistai.wireless":"JNCIS-MistAI Wireless","review.juniper-mist.advanced.wireless.implementation.with.mist":"Mist AI के साथ उन्नत वायरलेस कार्यान्वयन, समस्या निवारण और अनुकूलन सहित।","review.juniper-mist.jncip-mistai":"JNCIP-MistAI","review.juniper-mist.professional-level.expertise.in.complex.mist":"जटिल Mist AI तैनातियों और एकीकरणों में पेशेवर-स्तर की विशेषज्ञता।","review.juniper-mist.final.verdict":"अंतिम फैसला","review.juniper-mist.outstanding":"असाधारण","review.juniper-mist.juniper.mist.ai.sets.the":"Juniper Mist AI AI-संचालित नेटवर्किंग के लिए मानक निर्धारित करता है। Marvis वास्तव में रूपांतरकारी है - यह नेटवर्क टीमों के दिन-दर-दिन संचालन के तरीके को बदल देता है। उपयोगकर्ता अनुभव (SLEs) पर ध्यान केंद्रित करना, सिर्फ बुनियादी ढांचे के मेट्रिक्स नहीं ताज़ा है। जबकि केवल क्लाउड मॉडल और प्रीमियम मूल्य निर्धारण सभी के लिए उपयुक्त नहीं होगा, उन संगठनों के लिए जो इसे गले लगाते हैं, Mist असाधारण मूल्य प्रदान करता है।","review.juniper-mist.ai.capabilities":"AI क्षमताएं","review.juniper-mist.user.experience":"उपयोगकर्ता अनुभव","review.juniper-mist.wireless":"वायरलेस","review.juniper-mist.value.for.money":"पैसे के लिए मूल्य","review.juniper-mist.ecosystem":"पारिस्थितिकी तंत्र","review.juniper-mist.request.demo":"डेमो अनुरोध करें →","review.juniper-mist.compare.alternatives":"विकल्प की तुलना करें","review.common.screenshots.interface":"स्क्रीनशॉट और इंटरफेस","review.juniper-mist.explore.juniper.mist.ai-driven.networking":"Juniper Mist AI-संचालित नेटवर्किंग का अन्वेषण करें:","review.juniper-mist.frequently.asked.questions":"अक्सर पूछे जाने वाले सवाल","review.juniper-mist.faq.q1":"क्या Mist ऑफ़लाइन काम कर सकता है?","review.juniper-mist.faq.a1":"यदि क्लाउड कनेक्टिविटी खो जाती है तो नेटवर्क स्वयं काम करना जारी रखता है — AP और स्विच कैश्ड नीतियों का उपयोग करके काम करेंगे। हालांकि, AI सुविधाएं, प्रबंधन और Marvis को क्लाउड कनेक्टिविटी की आवश्यकता होती है। कोई ऑन-प्रिमाइसेस डिप्लॉयमेंट विकल्प नहीं है।","review.juniper-mist.faq.q2":"Marvis की Cisco AI से तुलना कैसे करें?","review.juniper-mist.faq.a2":"Marvis को आमतौर पर संवादी समस्या निवारण और प्राकृतिक भाषा प्रश्नों के लिए अधिक उन्नत माना जाता है। Cisco की DNA Center AI जटिल Cisco वातावरण में स्वचालित उपचार के लिए मजबूत है। Marvis उपयोगकर्ता अनुभव में जीतता है; Cisco एकीकरण गहराई में जीतता है।","review.juniper-mist.faq.q3":"क्या मुझे Mist के लिए Juniper स्विच की आवश्यकता है?","review.juniper-mist.faq.a3":"नहीं, Mist वायरलेस किसी भी स्विच अवसंरचना के साथ काम करता है। हालांकि, पूर्ण \"वायर्ड आश्वासन\" AI सुविधाओं और Marvis दृश्यमानता को तार वाले नेटवर्क में प्राप्त करने के लिए, आपको Mist के माध्यम से प्रबंधित Juniper EX स्विच की आवश्यकता है।","review.juniper-mist.faq.q4":"डेटा संप्रभुता के बारे में क्या?","review.juniper-mist.faq.a4":"Mist डेटा संप्रभुता आवश्यकताओं को पूरा करने के लिए क्षेत्रीय क्लाउड इंस्टेंस (US, EU, APAC) प्रदान करता है। आपका नेटवर्क डेटा चयनित क्षेत्र के भीतर रहता है। अत्यधिक विनियमित उद्योगों के लिए, Juniper के साथ विशिष्ट अनुपालन आवश्यकताओं पर चर्चा करें।"}
};

function getJuniperMistTranslation(key, lang) {
    if (junipermistTranslations[lang] && junipermistTranslations[lang][key]) {
        return junipermistTranslations[lang][key];
    }
    if (junipermistTranslations.en && junipermistTranslations.en[key]) {
        return junipermistTranslations.en[key];
    }
    return null;
}

function applyJuniperMistTranslations(lang) {
    console.log('Applying juniper-mist translations for:', lang);
    let count = 0;
    document.querySelectorAll('[data-i18n]').forEach(element => {
        const key = element.getAttribute('data-i18n');
        if (key && key.startsWith('review.juniper-mist.')) {
            const translation = getJuniperMistTranslation(key, lang);
            if (translation) {
                element.textContent = translation;
                count++;
            }
        }
    });
    console.log(`Applied ${count} juniper-mist translations`);
}

document.addEventListener('languageChanged', (e) => {
    const lang = e.detail.language;
    setTimeout(() => applyJuniperMistTranslations(lang), 200);
});

if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', () => {
        const currentLang = window.i18n ? window.i18n.getCurrentLanguage() : 'en';
        applyJuniperMistTranslations(currentLang);
    });
} else {
    const currentLang = window.i18n ? window.i18n.getCurrentLanguage() : 'en';
    applyJuniperMistTranslations(currentLang);
}

console.log('juniper-mist i18n loaded');
